import http from "node:http"
import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest"
import { Effect, Schema } from "effect"
import * as BrowserControlClient from "../src/browser-control-client.ts"
import { AuthenticatedJsonOutcome } from "../src/relay-schema.ts"
import { browserControlBuildId, browserControlVersion } from "../src/version.ts"

let server: http.Server
let endpoint: string
let authenticatedOutcome: unknown
let extensionFailuresRemaining = 0
let extensionChecks = 0

const session = {
  id: "x-live-chat-auth",
  createdAt: "2026-07-19T00:00:00.000Z",
  updatedAt: "2026-07-19T00:00:00.000Z",
  connected: true,
  pageUrl: "https://studio.x.com/live",
  stateKeys: [],
}

beforeAll(async () => {
  server = http.createServer((request, response) => {
    const path = new URL(request.url ?? "/", "http://localhost").pathname
    response.setHeader("content-type", "application/json")
    if (path === "/version") {
      response.end(JSON.stringify({ version: browserControlVersion, buildId: browserControlBuildId }))
      return
    }
    if (path === "/extension/status") {
      extensionChecks += 1
      const connected = extensionFailuresRemaining === 0
      extensionFailuresRemaining = Math.max(0, extensionFailuresRemaining - 1)
      response.end(JSON.stringify({ connected, version: "test", activeTargets: connected ? 1 : 0 }))
      return
    }
    const chunks: Buffer[] = []
    request.on("data", (chunk: Buffer) => chunks.push(chunk))
    request.on("end", () => {
      if (path === "/v1/sessions/ensure") {
        response.end(JSON.stringify({ session }))
        return
      }
      if (path === "/cli/session/reset") {
        response.end(JSON.stringify({ session }))
        return
      }
      if (path === "/v1/authenticated-origin/json") {
        response.end(JSON.stringify(authenticatedOutcome))
        return
      }
      response.writeHead(404)
      response.end(JSON.stringify({ error: "not found" }))
    })
  })
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve))
  const address = server.address()
  if (!address || typeof address === "string") throw new Error("Expected test server address")
  endpoint = `http://127.0.0.1:${address.port}`
})

afterAll(async () => {
  await new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve()))
})

beforeEach(() => {
  extensionFailuresRemaining = 0
  extensionChecks = 0
})

const makeOrigin = Effect.gen(function* () {
  const client = yield* BrowserControlClient.make({ endpoint })
  const liveSession = yield* client.ensureSession({ id: session.id })
  return yield* liveSession.authenticatedOrigin({
    origin: "https://studio.x.com",
    startUrl: "/live",
  })
})

describe("BrowserControlClient", () => {
  it("waits through a transient extension reconnect on an existing relay", async () => {
    extensionFailuresRemaining = 2
    await Effect.runPromise(BrowserControlClient.make({ endpoint }))
    expect(extensionChecks).toBe(3)
  })

  it("resets a named session", async () => {
    const result = await Effect.runPromise(Effect.gen(function* () {
      const client = yield* BrowserControlClient.make({ endpoint })
      return yield* client.resetSession(session.id)
    }))
    expect(result.id).toBe(session.id)
    expect(result.summary).toEqual(session)
  })

  it("schema-decodes authenticated JSON responses", async () => {
    authenticatedOutcome = AuthenticatedJsonOutcome.cases.Success.make({ status: 200, value: { rows: [{ id: "1" }] } })
    const result = await Effect.runPromise(Effect.gen(function* () {
      const origin = yield* makeOrigin
      return yield* origin.json({
        path: "/api/live/get-broadcasts?limit=1000",
        response: Schema.Struct({ rows: Schema.Array(Schema.Struct({ id: Schema.String })) }),
      })
    }))
    expect(result).toEqual({ rows: [{ id: "1" }] })
  })

  it("returns sensitive values as Redacted and redacts schema failures", async () => {
    const token = "<REDACTED>"
    authenticatedOutcome = AuthenticatedJsonOutcome.cases.Success.make({ status: 200, value: { accessToken: <REDACTED> } })
    const redacted = await Effect.runPromise(Effect.gen(function* () {
      const origin = yield* makeOrigin
      return yield* origin.json({
        path: "/api/live/get-chat-session",
        method: "POST",
        body: { broadcastId: "1" },
        response: Schema.Struct({ accessToken: <REDACTED> }),
        sensitive: true,
      })
    }))
    expect(String(redacted)).not.toContain(token)
    expect(BrowserControlClient.reveal(redacted)).toEqual({ accessToken: <REDACTED> })

    authenticatedOutcome = AuthenticatedJsonOutcome.cases.Success.make({ status: 200, value: { accessToken: <REDACTED> } })
    const error = await Effect.runPromise(Effect.gen(function* () {
      const origin = yield* makeOrigin
      return yield* origin.json({
        path: "/api/live/get-chat-session",
        response: Schema.Struct({ accessToken: <REDACTED> }),
        sensitive: true,
      })
    }).pipe(Effect.flip))
    expect(error.message).not.toContain(token)
    expect(String(error)).not.toContain(token)
  })

  it("reports mutating transport ambiguity as an unknown outcome", async () => {
    authenticatedOutcome = AuthenticatedJsonOutcome.cases.RequestFailed.make({ outcome: "unknown" })
    const error = await Effect.runPromise(Effect.gen(function* () {
      const origin = yield* makeOrigin
      return yield* origin.json({
        path: "/api/live/go-live",
        method: "POST",
        body: { title: "Private stream" },
        response: Schema.Unknown,
      })
    }).pipe(Effect.flip))
    expect(error).toBeInstanceOf(BrowserControlClient.RequestOutcomeUnknown)
  })

  it("provides direct Promise-based origin.get and origin.post with default headers", async () => {
    authenticatedOutcome = AuthenticatedJsonOutcome.cases.Success.make({ status: 200, value: { added: "Purple Magic" } })
    const client = BrowserControlClient.origin("https://www.ubereats.com", {
      session: session.id,
      endpoint,
      headers: { "x-csrf-token": "x" },
      handoffOnAuthFailure: true,
    })
    const result = await client.post("/_p/api/createDraftOrderV2", { item: "Purple Magic" })
    expect(result).toEqual({ added: "Purple Magic" })
  })
})

import { describe, expect, it } from "vitest"
import { CdpClientPool, ClientCdpSessionAlias } from "../src/cdp-client-pool.ts"
import type { CdpEvent } from "../src/protocol.ts"
import type { ChildTarget, ConnectedTarget } from "../src/relay-types.ts"

const rootTarget: ConnectedTarget = {
  tabId: 7,
  sessionId: "bc-tab-7",
  targetInfo: {
    targetId: "root-7",
    type: "page",
    title: "Root",
    url: "https://example.com/",
    attached: true,
    canAccessOpener: false,
  },
  owner: "user",
}

const childTarget: ChildTarget = {
  tabId: 7,
  sessionId: "chrome-child-7",
  parentSessionId: "bc-tab-7",
  targetInfo: {
    targetId: "child-7",
    type: "iframe",
    title: "Child",
    url: "https://child.example.com/",
    attached: true,
    canAccessOpener: false,
  },
  waitingForDebugger: false,
}

const grandchildTarget: ChildTarget = {
  ...childTarget,
  sessionId: "chrome-grandchild-7",
  parentSessionId: childTarget.sessionId,
  targetInfo: { ...childTarget.targetInfo, targetId: "grandchild-7" },
}

function setup() {
  const retired: Array<{ readonly client: { events: CdpEvent[] }; readonly sessionId: string }> = []
  const pool = new CdpClientPool<{ events: CdpEvent[] }>((client, event) => client.events.push(event), (client, sessionId) => retired.push({ client, sessionId }))
  const client: { events: CdpEvent[] } = { events: [] }
  pool.register(client)
  return { pool, client, events: client.events, retired }
}

describe("CdpClientPool", () => {
  it("treats named external clients as raw unless they identify a sandbox transport", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const named = {}, sandbox = {}, unnamed = {}
    pool.register(named, "alpha")
    pool.register(sandbox, "alpha", "sandbox")
    pool.register(unnamed, undefined, "sandbox")
    expect(pool.isSandbox(named)).toBe(false)
    expect(pool.isSandbox(sandbox)).toBe(true)
    expect(pool.isSandbox(unnamed)).toBe(false)
    pool.unregister(sandbox)
    expect(pool.isSandbox(sandbox)).toBe(false)
  })
  it("owns registration and cleanup for all per-client state", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const client = {}
    pool.register(client, "session-a")
    pool.setAutoAttachParams(client, { autoAttach: true, flatten: true })
    const aliasId = pool.createBrowserAlias(client)
    pool.announce(client, rootTarget)

    expect(pool.size).toBe(1)
    expect([...pool]).toEqual([client])
    expect(pool.sessionId(client)).toBe("session-a")
    expect(pool.autoAttachParams(client)).toEqual({ autoAttach: true, flatten: true })
    expect(pool.alias(client, aliasId)).toEqual(ClientCdpSessionAlias.Browser())
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(true)

    expect(pool.unregister(client)).toBeTypeOf("number")
    expect(pool.size).toBe(0)
    expect(pool.sessionId(client)).toBeUndefined()
    expect(pool.alias(client, aliasId)).toBeUndefined()
    expect(pool.autoAttachParams(client)).toBeUndefined()
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(false)

    pool.register(client)
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(false)
    expect(pool.alias(client, aliasId)).toBeUndefined()
  })

  it("keeps conflicting auto-attach settings scoped to their clients", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    const second = {}
    pool.register(first)
    pool.register(second)
    pool.setAutoAttachParams(first, { autoAttach: true, waitForDebuggerOnStart: false })
    pool.setAutoAttachParams(second, { autoAttach: false, waitForDebuggerOnStart: true })

    expect(pool.autoAttachParams(first)).toEqual({ autoAttach: true, waitForDebuggerOnStart: false })
    expect(pool.autoAttachParams(second)).toEqual({ autoAttach: false, waitForDebuggerOnStart: true })
    pool.setAutoAttachParams(first, undefined)
    expect(pool.autoAttachParams(first)).toBeUndefined()
    expect(pool.autoAttachParams(second)).toEqual({ autoAttach: false, waitForDebuggerOnStart: true })
  })

  it("rejects duplicate registration and aliases for unknown clients", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const client = {}
    pool.register(client)

    expect(() => pool.register(client)).toThrow("CDP client is already registered")
    expect(() => pool.createBrowserAlias({})).toThrow("CDP client is not registered")
    expect(() => pool.announce({}, rootTarget)).toThrow("CDP client is not registered")
  })

  it("invalidates an idle generation when another client registers", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    pool.register(first)
    const idleGeneration = pool.unregister(first)
    expect(idleGeneration).toBeDefined()
    if (idleGeneration === undefined) throw new Error("Expected idle generation")
    expect(pool.isCurrentIdleGeneration(idleGeneration)).toBe(true)

    pool.register({})
    expect(pool.isCurrentIdleGeneration(idleGeneration)).toBe(false)
  })

  it("produces an idle generation only when the last client leaves", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    const second = {}
    pool.register(first)
    pool.register(second)

    expect(pool.unregister(first)).toBeUndefined()
    const idleGeneration = pool.unregister(second)
    expect(idleGeneration).toBeDefined()
    expect(pool.unregister(second)).toBeUndefined()
  })

  it("routes root aliases without a Chrome session and child aliases with one", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const client = {}
    pool.register(client)

    const rootAlias = pool.createTargetAlias(client, rootTarget)
    const childAlias = pool.createTargetAlias(client, childTarget)

    expect(pool.alias(client, rootAlias)).toEqual(ClientCdpSessionAlias.Target({ tabId: 7, targetId: "root-7" }))
    expect(pool.alias(client, childAlias)).toEqual(ClientCdpSessionAlias.Target({
      tabId: 7,
      targetId: "child-7",
      chromeSessionId: "chrome-child-7",
    }))
  })

  it("detaches alias-only tabs across clients without touching browser aliases or other tabs", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    const second = {}
    pool.register(first)
    pool.register(second)
    const browserAlias = pool.createBrowserAlias(first)
    const firstTargetAlias = pool.createTargetAlias(first, rootTarget)
    const secondTargetAlias = pool.createTargetAlias(second, childTarget)
    const otherAlias = pool.createTargetAlias(first, {
      ...rootTarget,
      tabId: 8,
      sessionId: "bc-tab-8",
      targetInfo: { ...rootTarget.targetInfo, targetId: "root-8" },
    })

    pool.detachTab(7)
    pool.detachTab(7)

    expect(pool.alias(first, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
    expect(pool.alias(first, firstTargetAlias)).toBeUndefined()
    expect(pool.alias(second, secondTargetAlias)).toBeUndefined()
    expect(pool.alias(first, otherAlias)).toBeDefined()
  })

  it("prunes hidden alias-only targets for one client without touching another client", () => {
    const pool = new CdpClientPool<object>(() => {}, () => {})
    const first = {}
    const second = {}
    pool.register(first)
    pool.register(second)
    const firstAlias = pool.createTargetAlias(first, rootTarget)
    const secondAlias = pool.createTargetAlias(second, rootTarget)
    const browserAlias = pool.createBrowserAlias(first)

    pool.pruneInvisible(first, (tabId) => tabId !== 7)

    expect(pool.alias(first, firstAlias)).toBeUndefined()
    expect(pool.alias(second, secondAlias)).toBeDefined()
    expect(pool.alias(first, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
  })

  it("announces roots and children once per client with the correct parent envelope", () => {
    const { pool, client, events } = setup()
    const other: { events: CdpEvent[] } = { events: [] }
    pool.register(other)

    pool.announce(client, rootTarget)
    pool.announce(client, rootTarget)
    pool.announce(client, childTarget)
    pool.announce(client, childTarget)

    expect(events).toEqual([
      {
        method: "Target.attachedToTarget",
        params: { sessionId: rootTarget.sessionId, targetInfo: rootTarget.targetInfo, waitingForDebugger: false },
      },
      {
        sessionId: rootTarget.sessionId,
        method: "Target.attachedToTarget",
        params: { sessionId: childTarget.sessionId, targetInfo: childTarget.targetInfo, waitingForDebugger: false },
      },
    ])
    expect(other.events).toEqual([])
    expect(pool.hasSession(other, rootTarget.sessionId)).toBe(false)

    pool.announce(other, rootTarget)
    expect(other.events).toEqual([events[0]])
    expect(events).toHaveLength(2)
  })

  it("replaces the same target id under a new session after purging descendants and aliases", () => {
    const { pool, client, events } = setup()
    const aliases = [rootTarget, childTarget, grandchildTarget].map((target) => {
      pool.announce(client, target)
      return pool.createTargetAlias(client, target)
    })
    const browserAlias = pool.createBrowserAlias(client)
    events.length = 0

    pool.announce(client, { ...rootTarget, sessionId: "replacement-root-session" })

    expect(events).toEqual([
      {
        sessionId: childTarget.sessionId,
        method: "Target.detachedFromTarget",
        params: { sessionId: grandchildTarget.sessionId, targetId: grandchildTarget.targetInfo.targetId },
      },
      {
        sessionId: rootTarget.sessionId,
        method: "Target.detachedFromTarget",
        params: { sessionId: childTarget.sessionId, targetId: childTarget.targetInfo.targetId },
      },
      {
        method: "Target.detachedFromTarget",
        params: { sessionId: rootTarget.sessionId, targetId: rootTarget.targetInfo.targetId },
      },
      {
        method: "Target.attachedToTarget",
        params: { sessionId: "replacement-root-session", targetInfo: rootTarget.targetInfo, waitingForDebugger: false },
      },
    ])
    for (const target of [rootTarget, childTarget, grandchildTarget]) {
      expect(pool.hasSession(client, target.sessionId)).toBe(false)
    }
    for (const alias of aliases) expect(pool.alias(client, alias)).toBeUndefined()
    expect(pool.alias(client, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
    expect(pool.hasSession(client, "replacement-root-session")).toBe(true)
  })

  it("clears the previous identity when a session id is reused for a different target", () => {
    const { pool, client, events } = setup()
    pool.announce(client, rootTarget)
    pool.announce(client, childTarget)
    const rootAlias = pool.createTargetAlias(client, rootTarget)
    const childAlias = pool.createTargetAlias(client, childTarget)
    const replacement = { ...rootTarget, targetInfo: { ...rootTarget.targetInfo, targetId: "replacement-target" } }
    events.length = 0

    pool.announce(client, replacement)
    pool.announce(client, replacement)

    expect(events.map((event) => [event.method, event.params?.sessionId])).toEqual([
      ["Target.detachedFromTarget", childTarget.sessionId],
      ["Target.detachedFromTarget", rootTarget.sessionId],
      ["Target.attachedToTarget", rootTarget.sessionId],
    ])
    expect(events[1]?.params?.targetId).toBe(rootTarget.targetInfo.targetId)
    expect(events[2]?.params?.targetInfo).toEqual(replacement.targetInfo)
    expect(pool.alias(client, rootAlias)).toBeUndefined()
    expect(pool.alias(client, childAlias)).toBeUndefined()
    expect(pool.hasSession(client, childTarget.sessionId)).toBe(false)
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(true)
  })

  it("detaches duplicate child target ids on the old parent before re-announcing", () => {
    const { pool, client, events } = setup()
    pool.announce(client, childTarget)
    const alias = pool.createTargetAlias(client, childTarget)
    events.length = 0
    const replacement = { ...childTarget, sessionId: "replacement-child", parentSessionId: "replacement-parent" }

    pool.announce(client, replacement)

    expect(events).toEqual([
      {
        sessionId: rootTarget.sessionId,
        method: "Target.detachedFromTarget",
        params: { sessionId: childTarget.sessionId, targetId: childTarget.targetInfo.targetId },
      },
      {
        sessionId: "replacement-parent",
        method: "Target.attachedToTarget",
        params: { sessionId: "replacement-child", targetInfo: childTarget.targetInfo, waitingForDebugger: false },
      },
    ])
    expect(pool.alias(client, alias)).toBeUndefined()
    expect(pool.hasSession(client, childTarget.sessionId)).toBe(false)
    expect(pool.hasSession(client, replacement.sessionId)).toBe(true)
  })

  it.each([false, true])("detaches a tab's descendants before its root, idempotently (destroyed=%s)", (destroyed) => {
    const { pool, client, events } = setup()
    const other: { events: CdpEvent[] } = { events: [] }
    pool.register(other)
    for (const target of [rootTarget, childTarget, grandchildTarget]) pool.announce(client, target)
    events.length = 0

    pool.detachTab(rootTarget.tabId, { destroyed })
    pool.detachTab(rootTarget.tabId, { destroyed })

    expect(events.map((event) => [event.method, event.params?.targetId])).toEqual([
      ["Target.detachedFromTarget", grandchildTarget.targetInfo.targetId],
      ["Target.detachedFromTarget", childTarget.targetInfo.targetId],
      ...(destroyed ? [["Target.targetDestroyed", rootTarget.targetInfo.targetId]] : []),
      ["Target.detachedFromTarget", rootTarget.targetInfo.targetId],
    ])
    expect(events[0]?.sessionId).toBe(childTarget.sessionId)
    expect(events[1]?.sessionId).toBe(rootTarget.sessionId)
    expect(events.at(-1)?.sessionId).toBeUndefined()
    for (const target of [rootTarget, childTarget, grandchildTarget]) {
      expect(pool.hasSession(client, target.sessionId)).toBe(false)
    }
    expect(other.events).toEqual([])
  })

  it.each([false, true])("detaches a child subtree and its aliases without detaching the root (notify=%s)", (notify) => {
    const { pool, client, events } = setup()
    for (const target of [rootTarget, childTarget, grandchildTarget]) pool.announce(client, target)
    const rootAlias = pool.createTargetAlias(client, rootTarget)
    const childAlias = pool.createTargetAlias(client, childTarget)
    const grandchildAlias = pool.createTargetAlias(client, grandchildTarget)
    events.length = 0

    pool.detachTarget(childTarget, { notify })
    pool.detachTarget(childTarget, { notify })

    expect(events.map((event) => [event.method, event.params?.sessionId])).toEqual(notify ? [
      ["Target.detachedFromTarget", grandchildTarget.sessionId],
      ["Target.detachedFromTarget", childTarget.sessionId],
    ] : [])
    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(true)
    expect(pool.hasSession(client, childTarget.sessionId)).toBe(false)
    expect(pool.hasSession(client, grandchildTarget.sessionId)).toBe(false)
    expect(pool.alias(client, rootAlias)).toBeDefined()
    expect(pool.alias(client, childAlias)).toBeUndefined()
    expect(pool.alias(client, grandchildAlias)).toBeUndefined()
  })

  it("removes an unannounced child alias on target detach", () => {
    const { pool, client, events } = setup()
    const alias = pool.createTargetAlias(client, childTarget)

    pool.detachTarget(childTarget)

    expect(pool.alias(client, alias)).toBeUndefined()
    expect(events).toEqual([])
  })

  it("silently detaches a client-requested alias without detaching the real session", () => {
    const { pool, client, events, retired } = setup()
    pool.announce(client, rootTarget)
    pool.announce(client, childTarget)
    const rootAlias = pool.createTargetAlias(client, rootTarget)
    const childAlias = pool.createTargetAlias(client, childTarget)
    const browserAlias = pool.createBrowserAlias(client)
    events.length = 0

    for (const alias of [rootAlias, childAlias, browserAlias]) {
      pool.detach(client, alias)
      pool.detach(client, alias)
      expect(pool.alias(client, alias)).toBeUndefined()
    }

    expect(pool.hasSession(client, rootTarget.sessionId)).toBe(true)
    expect(pool.hasSession(client, childTarget.sessionId)).toBe(true)
    expect(events).toEqual([])
    expect(retired).toEqual([])
  })

  it.each(["root", "child"])("silently detaches a client-requested %s subtree only for that client and reports retired canonical sessions", (kind) => {
    const { pool, client, events, retired } = setup()
    const other: { events: CdpEvent[] } = { events: [] }
    pool.register(other)
    const browserAlias = pool.createBrowserAlias(client)
    const aliases = [rootTarget, childTarget, grandchildTarget].map((target) => {
      pool.announce(client, target)
      pool.announce(other, target)
      return pool.createTargetAlias(client, target)
    })
    events.length = 0
    other.events.length = 0

    const detached = kind === "root" ? rootTarget : childTarget
    pool.detach(client, detached.sessionId)
    pool.detach(client, detached.sessionId)
    pool.detach(client, "unannounced-session")
    expect(retired).toEqual([
      grandchildTarget.sessionId, childTarget.sessionId, ...(kind === "root" ? [rootTarget.sessionId] : []),
    ].map((sessionId) => ({ client, sessionId })))

    for (const target of [rootTarget, childTarget, grandchildTarget]) {
      expect(pool.hasSession(client, target.sessionId)).toBe(kind === "child" && target === rootTarget)
      expect(pool.hasSession(other, target.sessionId)).toBe(true)
    }
    for (const [index, alias] of aliases.entries()) {
      expect(pool.alias(client, alias) !== undefined).toBe(kind === "child" && index === 0)
    }
    expect(pool.alias(client, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
    expect(events).toEqual([])
    expect(other.events).toEqual([])
  })

  it("delivers events only to announced visible clients and prunes hidden subtrees", () => {
    const { pool, client, events, retired } = setup()
    const hidden: { events: CdpEvent[] } = { events: [] }
    const unannounced: { events: CdpEvent[] } = { events: [] }
    pool.register(hidden)
    pool.register(unannounced)
    for (const target of [rootTarget, childTarget]) {
      pool.announce(client, target)
      pool.announce(hidden, target)
    }
    const visibleAlias = pool.createTargetAlias(client, childTarget)
    const hiddenAlias = pool.createTargetAlias(hidden, childTarget)
    const browserAlias = pool.createBrowserAlias(hidden)
    events.length = 0
    hidden.events.length = 0
    const event: CdpEvent = { sessionId: childTarget.sessionId, method: "Runtime.executionContextsCleared", params: {} }

    pool.sendToViewers(rootTarget.sessionId, event, (viewer, tabId) => viewer !== hidden && tabId === 7)

    expect(events).toEqual([event])
    expect(unannounced.events).toEqual([])
    expect(hidden.events.map((event) => [event.method, event.params?.sessionId])).toEqual([
      ["Target.detachedFromTarget", childTarget.sessionId],
      ["Target.detachedFromTarget", rootTarget.sessionId],
    ])
    expect(pool.hasSession(hidden, rootTarget.sessionId)).toBe(false)
    expect(pool.hasSession(hidden, childTarget.sessionId)).toBe(false)
    // Announced retirements report through the same sink as silent ones.
    expect(retired).toEqual([childTarget.sessionId, rootTarget.sessionId].map((sessionId) => ({ client: hidden, sessionId })))
    expect(pool.alias(hidden, hiddenAlias)).toBeUndefined()
    expect(pool.alias(hidden, browserAlias)).toEqual(ClientCdpSessionAlias.Browser())
    expect(pool.alias(client, visibleAlias)).toBeDefined()

    hidden.events.length = 0
    pool.sendToViewers(rootTarget.sessionId, event, () => true)
    expect(hidden.events).toEqual([])
    expect(unannounced.events).toEqual([])
    expect(events).toEqual([event, event])
  })
})

import { Effect, Fiber, Latch } from "effect"
import { TestClock } from "effect/testing"
import { describe, expect, it } from "vitest"
import { CdpClientPool } from "../src/cdp-client-pool.ts"
import { CdpRouter } from "../src/cdp-router.ts"
import { CdpRuntime } from "../src/cdp-runtime.ts"
import type { CdpEvent, JsonObject } from "../src/protocol.ts"
import type { ChildTarget, ConnectedTarget } from "../src/relay-types.ts"
import { TargetRegistry } from "../src/target-registry.ts"

type Command = Parameters<ConstructorParameters<typeof CdpRuntime>[0]["send"]>[0]
type Viewer = { readonly events: CdpEvent[] }

function root(tabId = 1, sessionId = "root-session", targetId = "root-target"): ConnectedTarget {
  return {
    tabId, sessionId, owner: "user",
    targetInfo: { targetId, type: "page", title: "Runtime fixture", url: "https://example.test/", attached: true, canAccessOpener: false },
  }
}

function context(sessionId: string, isDefault = true, id = 1): CdpEvent {
  return { sessionId, method: "Runtime.executionContextCreated", params: { context: { id, auxData: { isDefault, frameId: "fixture-frame" } } } }
}

function frameTree(frameId = "fixture-frame"): JsonObject {
  return { frameTree: { frame: { id: frameId } } }
}

function fixture() {
  const registry = new TargetRegistry()
  const target = root()
  const child: ChildTarget = {
    tabId: target.tabId, sessionId: "child-session", parentSessionId: target.sessionId,
    targetInfo: { ...target.targetInfo, targetId: "child-target", type: "iframe" }, waitingForDebugger: false,
  }
  registry.addRootTarget(target)
  registry.addChildTarget(child)
  const clients = new CdpClientPool<Viewer>(() => {}, (viewer, sessionId) => runtime.detach(viewer, sessionId))
  const client: Viewer = { events: [] }
  clients.register(client, "owner")
  const router = new CdpRouter(clients, registry)
  const commands: Command[] = []
  const sent = Latch.makeUnsafe()
  const firstResult: JsonObject = { initial: true }
  const state: {
    generation: number
    intercept: (command: Command) => Effect.Effect<JsonObject, Error> | undefined
  } = { generation: 1, intercept: () => undefined }
  const runtime = new CdpRuntime<Viewer>({
    registry,
    generation: () => state.generation,
    sendEvent: (viewer, event) => viewer.events.push(event),
    send: (command) => Effect.suspend(() => {
      commands.push(command)
      sent.openUnsafe()
      return state.intercept(command) ?? Effect.succeed(firstResult)
    }),
  })
  const enable = (sessionId = target.sessionId, params: JsonObject = {}) => {
    const route = router.session(client, sessionId)
    if (!route) throw new Error("Fixture route not found")
    return runtime.enable(route, params, () => router.session(client, sessionId) !== undefined)
  }
  return { registry, target, child, clients, client, router, commands, sent, firstResult, state, runtime, enable }
}

describe("CdpRuntime", () => {
  const replayFixture = () => {
    const f = fixture()
    const route = { tabId: f.target.tabId, rootSessionId: f.target.sessionId }
    const permitted = () => f.clients.has(f.client) && f.router.session(f.client, route.rootSessionId) !== undefined
    const response = f.runtime.frameTreeResponse(f.client, route, permitted)
    const frameSent = () => response(frameTree())
    const enable = () => f.runtime.enable(route, {}, permitted, f.client)
    return { ...f, route, events: f.client.events, frameSent, enable }
  }

  it("replays full contexts to a second canonical client without advancing the clock or resetting Runtime", async () => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = replayFixture()
      const firstClient: Viewer = { events: [] }
      f.runtime.frameTreeResponse(firstClient, f.route, () => true)(frameTree())
      const event: CdpEvent = { sessionId: f.target.sessionId, method: "Runtime.executionContextCreated", params: {
        context: { id: 7, uniqueId: "fixture-unique", name: "", origin: "https://example.test", auxData: { isDefault: true, frameId: "fixture-frame" } },
      } }
      f.runtime.notify(event)
      f.runtime.deliver(firstClient, event)
      f.frameSent()
      expect(yield* f.enable()).toBe(f.firstResult)
      expect(f.events).toEqual([event])
      expect(firstClient.events).toEqual([event])
      // Native duplicates after replay must not replace Playwright's existing world.
      f.runtime.deliver(f.client, event)
      expect(f.events).toEqual([event])
      expect(f.commands.map((command) => command.method)).toEqual(["Runtime.enable"])
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it.each(["cached", "native"])("waits for the outbound frame-tree response before %s replay", async (kind) => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = replayFixture()
      const event = context(f.target.sessionId)
      if (kind === "cached") f.runtime.notify(event)
      else f.state.intercept = () => { f.runtime.notify(event); return undefined }
      const fiber = yield* f.enable().pipe(Effect.forkChild)
      yield* f.sent.await
      yield* TestClock.adjust(1)
      expect(fiber.pollUnsafe()).toBeUndefined()
      expect(f.events).toEqual([])
      f.frameSent()
      expect(yield* Fiber.join(fiber)).toBe(f.firstResult)
      expect(f.events).toEqual([event])
      expect(f.commands).toHaveLength(1)
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it.each(["destroyed", "cleared", "frame-detached", "overflow", "disable", "disable-in-flight", "replacement", "generation", "ownership", "disconnect", "visibility"])("rejects cached contexts after %s", async (kind) => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = replayFixture()
      f.runtime.notify(context(f.target.sessionId))
      f.frameSent()
      if (kind === "destroyed") f.runtime.notify({ sessionId: f.target.sessionId, method: "Runtime.executionContextDestroyed", params: { executionContextId: 1 } })
      if (kind === "cleared") f.runtime.notify({ sessionId: f.target.sessionId, method: "Runtime.executionContextsCleared" })
      if (kind === "frame-detached") f.runtime.notify({ sessionId: f.target.sessionId, method: "Page.frameDetached", params: { frameId: "fixture-frame" } })
      if (kind === "overflow") for (let id = 2; id <= 513; id++) f.runtime.notify(context(f.target.sessionId, false, id))
      if (kind === "disable" || kind === "disable-in-flight") {
        const done = f.runtime.beginDisable(f.target.tabId)
        if (kind === "disable") done()
        else f.runtime.notify(context(f.target.sessionId))
      }
      if (kind === "replacement") f.registry.addRootTarget(root(1, "successor", "successor-target"))
      if (kind === "generation") f.state.generation++
      if (kind === "ownership") f.registry.reserveTargetOwnership(f.target.targetInfo.targetId, "other")
      if (kind === "disconnect") f.runtime.disconnect(f.client)
      if (kind === "visibility") f.clients.unregister(f.client)
      const fiber = yield* f.enable().pipe(Effect.exit, Effect.forkChild)
      yield* TestClock.adjust(6_000)
      yield* Fiber.join(fiber)
      expect(f.events).toEqual([])
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it("keeps aliases on fallback despite a populated canonical cache", async () => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = replayFixture()
      f.frameSent()
      f.runtime.notify(context(f.target.sessionId))
      const alias = f.clients.createTargetAlias(f.client, f.target)
      const route = f.router.session(f.client, alias)
      if (!route) throw new Error("Missing alias")
      const fiber = yield* f.runtime.enable(route, {}, () => f.router.session(f.client, alias) !== undefined).pipe(Effect.forkChild)
      yield* f.sent.await
      yield* TestClock.adjust(3_000)
      expect(f.commands.map((command) => command.method)).toEqual(["Runtime.enable", "Runtime.disable", "Runtime.enable"])
      yield* TestClock.adjust(3_000)
      yield* Fiber.join(fiber)
      expect(f.events).toEqual([])
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it.each(["generation", "ownership", "disconnect", "announcement"])("does not replay through an outstanding frame-tree response after %s changes", async (kind) => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = replayFixture()
      f.runtime.notify(context(f.target.sessionId))
      const fiber = yield* f.enable().pipe(Effect.forkChild)
      yield* f.sent.await
      yield* TestClock.adjust(1)
      if (kind === "generation") f.state.generation++
      if (kind === "ownership") f.registry.reserveTargetOwnership(f.target.targetInfo.targetId, "other")
      if (kind === "disconnect") { f.runtime.disconnect(f.client); f.clients.unregister(f.client) }
      if (kind === "announcement") {
        f.clients.announce(f.client, f.target)
        f.clients.detach(f.client, f.target.sessionId)
        f.clients.unregister(f.client)
      }
      f.frameSent()
      yield* TestClock.adjust(6_000)
      yield* Fiber.join(fiber)
      expect(f.events).toEqual([])
      expect(f.commands.map((command) => command.method)).toEqual(["Runtime.enable"])
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it("does not replay before the original enable ACK, and preserves its error", async () => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = replayFixture()
      const ack = yield* Latch.make()
      f.runtime.notify(context(f.target.sessionId))
      f.frameSent()
      const failure = new Error("enable denied")
      f.state.intercept = () => ack.await.pipe(Effect.andThen(Effect.fail(failure)))
      const fiber = yield* f.enable().pipe(Effect.flip, Effect.forkChild)
      yield* f.sent.await
      expect(f.events).toEqual([])
      yield* ack.open
      expect(yield* Fiber.join(fiber)).toBe(failure)
      expect(f.events).toEqual([])
      expect(f.commands).toHaveLength(1)
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it("preserves raw canonical clients that never request a frame tree", async () => {
