      expect(enable.pollUnsafe()).toBeUndefined()
      yield* TestClock.adjust(1)
      expect(yield* Fiber.join(enable)).toBe(f.firstResult)
      yield* TestClock.adjust(10_000)
      expect(f.commands).toHaveLength(3)
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it("starts the recovery window before a slow disable ACK", async () => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = fixture()
      const disabling = yield* Latch.make()
      const ack = yield* Latch.make()
      f.state.intercept = (command) => command.method === "Runtime.disable"
        ? disabling.open.pipe(Effect.andThen(ack.await), Effect.as({}))
        : undefined
      const enable = yield* f.enable().pipe(Effect.forkChild)
      yield* f.sent.await
      yield* TestClock.adjust(3_000)
      yield* disabling.await
      yield* TestClock.adjust(3_001)
      expect(enable.pollUnsafe()).toBeUndefined()
      yield* ack.open
      expect(yield* Fiber.join(enable)).toBe(f.firstResult)
      expect(f.commands.map((command) => command.method)).toEqual(["Runtime.enable", "Runtime.disable", "Runtime.enable"])
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it.each(["Runtime.disable", "Runtime.enable", "both"])("keeps recovery failure soft for %s", async (failure) => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = fixture()
      f.state.intercept = (command) => f.commands.length > 1 && (failure === "both" || command.method === failure)
        ? Effect.fail(new Error("Recovery command failed"))
        : undefined
      const enable = yield* f.enable().pipe(Effect.forkChild)
      yield* f.sent.await
      yield* TestClock.adjust(6_000)
      expect(yield* Fiber.join(enable)).toBe(f.firstResult)
      expect(f.commands.map((command) => command.method)).toEqual(["Runtime.enable", "Runtime.disable", "Runtime.enable"])
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it.each(["same-session", "same-target", "detached", "staged"])("does not recover a retired root: %s", async (change) => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = fixture()
      const enable = yield* f.enable().pipe(Effect.forkChild)
      yield* f.sent.await
      if (change === "detached") f.registry.detachRootTargetState(1)
      else if (change === "staged") f.registry.stageRootTarget(root(1, "successor-session", "successor-target"))
      else f.registry.addRootTarget(root(1, change === "same-session" ? f.target.sessionId : "successor-session", change === "same-target" ? f.target.targetInfo.targetId : "successor-target"))
      yield* TestClock.adjust(3_000)
      expect(f.commands).toHaveLength(1)
      expect(yield* Fiber.join(enable)).toBe(f.firstResult)
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it.each(["same-session", "same-target", "new-parent"])("skips retry enable when a child changes during disable: %s", async (change) => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = fixture()
      const disabling = yield* Latch.make()
      const ack = yield* Latch.make()
      f.state.intercept = (command) => command.method === "Runtime.disable"
        ? disabling.open.pipe(Effect.andThen(ack.await), Effect.as({}))
        : undefined
      const enable = yield* f.enable(f.child.sessionId).pipe(Effect.forkChild)
      yield* f.sent.await
      yield* TestClock.adjust(3_000)
      yield* disabling.await
      f.registry.addChildTarget({
        ...f.child,
        sessionId: change === "same-target" ? "successor-child" : f.child.sessionId,
        parentSessionId: change === "new-parent" ? "successor-parent" : f.child.parentSessionId,
        targetInfo: { ...f.child.targetInfo, targetId: change === "same-session" ? "successor-child-target" : f.child.targetInfo.targetId },
      })
      expect(enable.pollUnsafe()).toBeUndefined()
      yield* ack.open
      yield* TestClock.adjust(3_000)
      expect(yield* Fiber.join(enable)).toBe(f.firstResult)
      expect(f.commands).toEqual([
        { tabId: 1, sessionId: f.child.sessionId, method: "Runtime.enable", params: {} },
        { tabId: 1, sessionId: f.child.sessionId, method: "Runtime.disable", params: {} },
      ])
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it.each([
    { change: "extension", phase: "waiting" },
    { change: "visibility", phase: "waiting" },
    { change: "disconnect", phase: "waiting" },
    { change: "extension", phase: "disabling" },
    { change: "visibility", phase: "disabling" },
    { change: "disconnect", phase: "disabling" },
  ])("skips unsent recovery after $change changes while $phase", async ({ change, phase }) => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = fixture()
      const disabling = yield* Latch.make()
      const ack = yield* Latch.make()
      f.state.intercept = (command) => command.method === "Runtime.disable"
        ? disabling.open.pipe(Effect.andThen(ack.await), Effect.as({}))
        : undefined
      const enable = yield* f.enable().pipe(Effect.forkChild)
      yield* f.sent.await
      if (phase === "disabling") {
        yield* TestClock.adjust(3_000)
        yield* disabling.await
      }
      if (change === "extension") f.state.generation += 1
      else if (change === "disconnect") f.clients.unregister(f.client)
      else f.registry.reserveTargetOwnership(f.target.targetInfo.targetId, "other-owner")
      yield* ack.open
      yield* TestClock.adjust(3_000)
      expect(yield* Fiber.join(enable)).toBe(f.firstResult)
      expect(f.commands.map((command) => command.method)).toEqual(phase === "waiting" ? ["Runtime.enable"] : ["Runtime.enable", "Runtime.disable"])
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it.each(["detached", "hidden", "disconnected"])("rejects an initially %s route without sending", async (change) => {
    await Effect.runPromise(Effect.gen(function* () {
      const f = fixture()
      const enable = f.enable()
      if (change === "detached") f.registry.detachRootTargetState(1)
      else if (change === "disconnected") f.clients.unregister(f.client)
      else f.registry.reserveTargetOwnership(f.target.targetInfo.targetId, "other-owner")
      expect((yield* Effect.flip(enable)).message).toBe("CDP target changed before Runtime.enable")
      expect(f.commands).toEqual([])
    }))
  })

  it.each(["failure", "interruption"])("does not recover or reuse earlier context after initial %s", async (outcome) => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = fixture()
      const error = new Error("Initial enable failed")
      f.state.intercept = () => outcome === "failure" ? Effect.fail(error) : Effect.never
      const enable = yield* f.enable().pipe(Effect.flip, Effect.forkChild)
      yield* f.sent.await
      if (outcome === "failure") expect(yield* Fiber.join(enable)).toBe(error)
      else yield* Fiber.interrupt(enable)
      f.runtime.notify(context(f.target.sessionId))
      yield* TestClock.adjust(10_000)
      expect(f.commands).toHaveLength(1)
      f.state.intercept = () => undefined
      const next = yield* f.enable().pipe(Effect.forkChild)
      yield* TestClock.adjust(2_999)
      expect(next.pollUnsafe()).toBeUndefined()
      f.runtime.notify(context(f.target.sessionId))
      expect(yield* Fiber.join(next)).toBe(f.firstResult)
      expect(f.commands).toHaveLength(2)
    })).pipe(Effect.provide(TestClock.layer())))
  })

  it("disables roots before children with the correct Chrome addresses", async () => {
    await Effect.runPromise(Effect.gen(function* () {
      const f = fixture()
      f.registry.addRootTarget(root(2, "second-session", "second-target"))
      yield* f.runtime.disableIdle(() => true)
      expect(f.commands).toEqual([
        { tabId: 1, method: "Runtime.disable", params: {} },
        { tabId: 2, method: "Runtime.disable", params: {} },
        { tabId: 1, sessionId: f.child.sessionId, method: "Runtime.disable", params: {} },
      ])
    }))
  })

  it.each(["client", "extension", "later-root", "staged-root"])("lets the first idle command settle but skips stale work after a %s change", async (change) => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const f = fixture()
      f.registry.addRootTarget(root(2, "second-session", "second-target"))
      const generation = f.clients.unregister(f.client)
      if (generation === undefined) throw new Error("Expected idle generation")
      const ack = yield* Latch.make()
      f.state.intercept = () => f.commands.length === 1 ? ack.await.pipe(Effect.as({})) : undefined
      const idle = yield* f.runtime.disableIdle(() => f.clients.isCurrentIdleGeneration(generation)).pipe(Effect.forkChild)
      yield* f.sent.await
      if (change === "client") f.clients.register({ events: [] })
      else if (change === "extension") f.state.generation += 1
      else if (change === "staged-root") f.registry.stageRootTarget(root(2, "successor-session", "successor-target"))
      else f.registry.addRootTarget(root(2, "second-session", "successor-target"))
      expect(idle.pollUnsafe()).toBeUndefined()
      expect(f.commands).toHaveLength(1)
      yield* ack.open
      yield* Fiber.join(idle)
      expect(f.commands).toEqual([
        { tabId: 1, method: "Runtime.disable", params: {} },
        ...(change === "later-root" || change === "staged-root" ? [{ tabId: 1, sessionId: f.child.sessionId, method: "Runtime.disable", params: {} }] : []),
      ])
    })))
  })
})

import { fileURLToPath } from "node:url"
import { NodeHttpClient } from "@effect/platform-node"
import { Context, Effect, Layer, Match, Redacted, Schema } from "effect"
import * as AuthenticatedOriginInternal from "./authenticated-origin.ts"
import * as RelayClient from "./relay-client.ts"
import * as RelayLifecycle from "./relay-lifecycle.ts"
import type {
  AuthenticatedJsonMethod,
  AuthenticatedJsonOutcome,
  SessionSummary,
} from "./relay-schema.ts"

export type Json = Schema.Schema.Type<typeof Schema.Json>

export class ClientError extends Schema.TaggedError<ClientError>()(
  "BrowserControlClient.Error",
  {
    message: Schema.String,
    reason: Schema.Literals(["connect", "session", "invalid-request"]),
    code: Schema.optionalKey(Schema.String),
    status: Schema.optionalKey(Schema.Number),
  },
) {}

export class OriginMismatch extends Schema.TaggedError<OriginMismatch>()(
  "AuthenticatedOrigin.OriginMismatch",
  {
    expectedOrigin: Schema.String,
    actualOrigin: Schema.String,
    message: Schema.String,
  },
) {}

export class HttpError extends Schema.TaggedError<HttpError>()(
  "AuthenticatedOrigin.HttpError",
  {
    status: Schema.Number,
    method: Schema.String,
    message: Schema.String,
  },
) {}

export class RequestFailed extends Schema.TaggedError<RequestFailed>()(
  "AuthenticatedOrigin.RequestFailed",
  {
    method: Schema.String,
    message: Schema.String,
  },
) {}

export class RequestOutcomeUnknown extends Schema.TaggedError<RequestOutcomeUnknown>()(
  "AuthenticatedOrigin.RequestOutcomeUnknown",
  {
    method: Schema.String,
    message: Schema.String,
  },
) {}

export class InvalidResponse extends Schema.TaggedError<InvalidResponse>()(
  "AuthenticatedOrigin.InvalidResponse",
  {
    reason: Schema.Literals(["invalid-json", "too-large"]),
    status: Schema.Number,
    maxResponseBytes: Schema.optionalKey(Schema.Number),
    message: Schema.String,
  },
) {}

export class ResponseDecodeFailed extends Schema.TaggedError<ResponseDecodeFailed>()(
  "AuthenticatedOrigin.ResponseDecodeFailed",
  {
    message: Schema.String,
  },
) {}

export class SensitiveCaptureActive extends Schema.TaggedError<SensitiveCaptureActive>()(
  "AuthenticatedOrigin.SensitiveCaptureActive",
  {
    message: Schema.String,
  },
) {}

export type Error =
  | ClientError
  | OriginMismatch
  | HttpError
  | RequestFailed
  | RequestOutcomeUnknown
  | InvalidResponse
  | ResponseDecodeFailed
  | SensitiveCaptureActive

export interface JsonOptions<S extends Schema.Top> {
  readonly path: `/${string}`
  readonly method?: AuthenticatedJsonMethod
  readonly headers?: Readonly<Record<string, string>>
  readonly body?: Json
  readonly response: S
  readonly sensitive?: boolean
  readonly handoffOnAuthFailure?: boolean
  readonly handoffMessage?: string
  readonly timeoutMs?: number
  readonly maxResponseBytes?: number
}

export interface AuthenticatedOriginCapability {
  readonly origin: string
  readonly json: {
    <S extends Schema.Top>(
      options: JsonOptions<S> & { readonly sensitive: true },
    ): Effect.Effect<Redacted.Redacted<S["Type"]>, Error, S["DecodingServices"]>
    <S extends Schema.Top>(
      options: JsonOptions<S> & { readonly sensitive?: false },
    ): Effect.Effect<S["Type"], Error, S["DecodingServices"]>
  }
}

export type AuthenticatedOrigin = AuthenticatedOriginCapability

/** Reveal a sensitive response using Browser Control's Effect runtime. */
export const reveal = <A>(value: Redacted.Redacted<A>): A => Redacted.value(value)

export interface AuthenticatedOriginOptions {
  readonly origin: string
  /** Explicitly navigate here when the session page is not already on `origin`. */
  readonly startUrl?: string
  /** Default headers merged into every request on this origin. */
  readonly headers?: Readonly<Record<string, string>>
  /** Present an in-page handoff prompt and retry once if the session is logged out or redirected to auth. */
  readonly handoffOnAuthFailure?: boolean
  readonly handoffMessage?: string
}

export interface OriginClientOptions extends Omit<AuthenticatedOriginOptions, "origin"> {
  readonly session: string
  readonly readOnly?: boolean
  readonly endpoint?: string
}

export interface OriginClient {
  readonly origin: string
  readonly session: string
  readonly get: <T = unknown>(
    path: `/${string}`,
    options?: { readonly headers?: Readonly<Record<string, string>>; readonly timeoutMs?: number },
  ) => Promise<T>
  readonly post: <T = unknown>(
    path: `/${string}`,
    body?: Json,
    options?: { readonly headers?: Readonly<Record<string, string>>; readonly timeoutMs?: number },
  ) => Promise<T>
  readonly json: AuthenticatedOriginCapability["json"]
}

export interface Session {
  readonly id: string
  readonly summary: SessionSummary
  readonly authenticatedOrigin: (
    options: AuthenticatedOriginOptions,
  ) => Effect.Effect<AuthenticatedOriginCapability, ClientError>
}

export interface EnsureSessionOptions {
  readonly id: string
  readonly readOnly?: boolean
}

export interface Interface {
  readonly ensureSession: (
    options: EnsureSessionOptions,
  ) => Effect.Effect<Session, ClientError>
  readonly resetSession: (id: string) => Effect.Effect<Session, ClientError>
}

export interface MakeOptions {
  readonly endpoint?: string
}

export class Service extends Context.Service<Service, Interface>()(
  "@opencode-ai/browser-control/BrowserControlClient",
) {}

export const make = Effect.fn("BrowserControlClient.make")(function* (options: MakeOptions = {}) {
  const relay = yield* RelayClient.make(options).pipe(
    Effect.provide(NodeHttpClient.layerNodeHttp),
    Effect.mapError((error) => clientError("connect", error)),
  )
  const readiness = yield* RelayLifecycle.ensureRelay({
    relay,
    // The consumer may run under Bun; the relay is a Node application.
    start: RelayLifecycle.startManagedRelay(fileURLToPath(import.meta.url), "node", []),
  }).pipe(Effect.mapError((error) => clientError("connect", error)))
  if (readiness.buildProblem) {
    return yield* new ClientError({
      message: readiness.buildProblem,
      reason: "connect",
    })
  }
  yield* RelayLifecycle.ensureExtensionConnected({
    relay,
    waitForReconnect: true,
  }).pipe(Effect.mapError((error) => clientError("connect", error)))

  const ensureSession = Effect.fn("BrowserControlClient.ensureSession")(function* (
    sessionOptions: EnsureSessionOptions,
  ) {
    const summary = yield* relay.sessionEnsure(sessionOptions.id, {
      ...(sessionOptions.readOnly === undefined ? {} : { readOnly: sessionOptions.readOnly }),
    }).pipe(Effect.mapError((error) => clientError("session", error)))
    return makeSession(relay, summary)
  })

  const resetSession = Effect.fn("BrowserControlClient.resetSession")(function* (id: string) {
    const summary = yield* relay.sessionReset(id).pipe(
      Effect.mapError((error) => clientError("session", error)),
    )
    return makeSession(relay, summary)
  })

  return Service.of({ ensureSession, resetSession })
})

export const layer = (options: MakeOptions = {}): Layer.Layer<Service, ClientError> =>
  Layer.effect(Service, make(options))

export function origin(originUrl: string, options: OriginClientOptions): OriginClient {
  const normalizedOrigin = AuthenticatedOriginInternal.normalizeOrigin(originUrl)
  let cachedOrigin: Promise<AuthenticatedOriginCapability> | undefined
  const resolveOrigin = (): Promise<AuthenticatedOriginCapability> => {
    cachedOrigin ??= Effect.runPromise(
      Effect.gen(function* () {
        const client = yield* make(options.endpoint ? { endpoint: options.endpoint } : {})
        const liveSession = yield* client.ensureSession({
          id: options.session,
          ...(options.readOnly === undefined ? {} : { readOnly: options.readOnly }),
        })
        return yield* liveSession.authenticatedOrigin({
          origin: normalizedOrigin,
          startUrl: options.startUrl ?? "/",
          ...(options.headers ? { headers: options.headers } : {}),
          ...(options.handoffOnAuthFailure === undefined ? {} : { handoffOnAuthFailure: options.handoffOnAuthFailure }),
          ...(options.handoffMessage ? { handoffMessage: options.handoffMessage } : {}),
        })
      }),
    ).catch((error) => {
      cachedOrigin = undefined
      throw error
    })
    return cachedOrigin
  }
  const json: AuthenticatedOriginCapability["json"] = ((request: JsonOptions<Schema.Top>) =>
    Effect.promise(resolveOrigin).pipe(
      Effect.flatMap((cap) => cap.json(request as JsonOptions<Schema.Top> & { readonly sensitive?: false })),
    )) as AuthenticatedOriginCapability["json"]

  return {
    origin: normalizedOrigin,
    session: options.session,
    get: async <T = unknown>(path: `/${string}`, callOptions?: { readonly headers?: Readonly<Record<string, string>>; readonly timeoutMs?: number }) => {
      const cap = await resolveOrigin()
      return (await Effect.runPromise(cap.json({
        path,
        method: "GET",
        ...(callOptions?.headers ? { headers: callOptions.headers } : {}),
        ...(callOptions?.timeoutMs === undefined ? {} : { timeoutMs: callOptions.timeoutMs }),
        response: Schema.Json,
      }))) as T
    },
    post: async <T = unknown>(path: `/${string}`, body?: Json, callOptions?: { readonly headers?: Readonly<Record<string, string>>; readonly timeoutMs?: number }) => {
      const cap = await resolveOrigin()
      return (await Effect.runPromise(cap.json({
        path,
        method: "POST",
        ...(body === undefined ? {} : { body }),
        ...(callOptions?.headers ? { headers: callOptions.headers } : {}),
        ...(callOptions?.timeoutMs === undefined ? {} : { timeoutMs: callOptions.timeoutMs }),
        response: Schema.Json,
      }))) as T
    },
    json,
  }
}

function makeSession(relay: RelayClient.Interface, summary: SessionSummary): Session {
  return {
    id: summary.id,
    summary,
    authenticatedOrigin: (options) => Effect.try({
      try: () => makeAuthenticatedOrigin(relay, summary.id, options),
      catch: (cause) => cause instanceof ClientError
        ? cause
        : new ClientError({
            message: cause instanceof globalThis.Error ? cause.message : "Invalid authenticated origin",
            reason: "invalid-request",
          }),
    }),
  }
}

function makeAuthenticatedOrigin(
  relay: RelayClient.Interface,
  sessionId: string,
  options: AuthenticatedOriginOptions,
): AuthenticatedOrigin {
  const origin = AuthenticatedOriginInternal.normalizeOrigin(options.origin)
  const startUrl = options.startUrl === undefined ? undefined : AuthenticatedOriginInternal.resolveStartUrl(origin, options.startUrl)

  function json<S extends Schema.Top>(
    request: JsonOptions<S> & { readonly sensitive: true },
  ): Effect.Effect<Redacted.Redacted<S["Type"]>, Error, S["DecodingServices"]>
  function json<S extends Schema.Top>(
    request: JsonOptions<S> & { readonly sensitive?: false },
  ): Effect.Effect<S["Type"], Error, S["DecodingServices"]>
  function json<S extends Schema.Top>(
    request: JsonOptions<S>,
  ): Effect.Effect<S["Type"] | Redacted.Redacted<S["Type"]>, Error, S["DecodingServices"]> {
    const method = request.method ?? "GET"
    if (method === "GET" && request.body !== undefined) {
      return Effect.fail(new ClientError({
        message: "GET authenticated origin requests cannot include a body",
        reason: "invalid-request",
      }))
    }
    const mutation = method !== "GET"
    const mergedHeaders =
      options.headers || request.headers
        ? { ...(options.headers ?? {}), ...(request.headers ?? {}) }
        : undefined
    const handoffOnAuthFailure = request.handoffOnAuthFailure ?? options.handoffOnAuthFailure
    const handoffMessage = request.handoffMessage ?? options.handoffMessage
    return relay.authenticatedJson({
      sessionId,
      origin,
      ...(startUrl ? { startUrl } : {}),
      method,
      path: request.path,
      ...(mergedHeaders ? { headers: mergedHeaders } : {}),
      ...(request.body === undefined ? {} : { body: request.body }),
      ...(request.sensitive === true ? { sensitive: true } : {}),
      ...(handoffOnAuthFailure === undefined ? {} : { handoffOnAuthFailure }),
      ...(handoffMessage === undefined ? {} : { handoffMessage }),
      ...(request.timeoutMs === undefined ? {} : { timeoutMs: request.timeoutMs }),
      ...(request.maxResponseBytes === undefined ? {} : { maxResponseBytes: request.maxResponseBytes }),
    }).pipe(
      Effect.mapError((error): Error => mutation && (
          error instanceof RelayClient.RelayUnreachable || error instanceof RelayClient.RelayDecodeFailed
        )
        ? unknownOutcome(method)
        : clientError("session", error)),
      Effect.flatMap((outcome) => decodeOutcome(outcome, method, mutation, request)),
    )
  }

  return { origin, json }
}

function decodeOutcome<S extends Schema.Top>(
  outcome: AuthenticatedJsonOutcome,
  method: AuthenticatedJsonMethod,
  mutation: boolean,
  request: JsonOptions<S>,
): Effect.Effect<S["Type"] | Redacted.Redacted<S["Type"]>, Error, S["DecodingServices"]> {
  return Match.valueTags(outcome, {
    Success: (outcome) => {
      if (request.sensitive === true) {
        return Schema.decodeUnknownEffect(Schema.RedactedFromValue(request.response, {
          label: "Browser Control authenticated response",
          disallowEncode: true,
        }))(outcome.value).pipe(
          Effect.mapError(() => mutation
            ? unknownOutcome(method)
            : new ResponseDecodeFailed({ message: "Sensitive authenticated response did not match the expected schema" })),
        )
      }
      return Schema.decodeUnknownEffect(request.response)(outcome.value).pipe(
        Effect.mapError((cause) => mutation
          ? unknownOutcome(method)
          : new ResponseDecodeFailed({ message: `Authenticated response did not match the expected schema: ${cause.message}` })),
      )
    },
    OriginMismatch: (outcome) =>
      Effect.fail(new OriginMismatch({
        expectedOrigin: outcome.expectedOrigin,
        actualOrigin: outcome.actualOrigin,
        message: `Session page origin ${outcome.actualOrigin} does not match ${outcome.expectedOrigin}`,
      })),
    HttpError: (outcome) =>
      Effect.fail(new HttpError({
        status: outcome.status,
        method,
        message: `Authenticated ${method} request was rejected with HTTP ${outcome.status}`,
      })),
    RequestFailed: (outcome) =>
      Effect.fail(mutation || outcome.outcome === "unknown"
        ? unknownOutcome(method)
        : new RequestFailed({ method, message: `Authenticated ${method} request failed before it was sent` })),
    InvalidJson: (outcome) =>
      Effect.fail(mutation
        ? unknownOutcome(method)
        : new InvalidResponse({
            reason: "invalid-json",
            status: outcome.status,
            message: "Authenticated response was not valid JSON",
          })),
    ResponseTooLarge: (outcome) =>
      Effect.fail(mutation
        ? unknownOutcome(method)
        : new InvalidResponse({
            reason: "too-large",
            status: outcome.status,
            maxResponseBytes: outcome.maxResponseBytes,
            message: `Authenticated response exceeded ${outcome.maxResponseBytes} bytes`,
          })),
    SensitiveCaptureActive: () =>
      Effect.fail(new SensitiveCaptureActive({
        message: "Sensitive authenticated requests are blocked while session network capture is active",
      })),
  })
}

function unknownOutcome(method: AuthenticatedJsonMethod): RequestOutcomeUnknown {
  return new RequestOutcomeUnknown({
    method,
    message: `Authenticated ${method} request outcome is unknown; reconcile state before retrying`,
  })
}

function clientError(reason: ClientError["reason"], error: unknown): ClientError {
  if (error instanceof ClientError) return error
  if (error instanceof RelayClient.RelayRejected) {
    return new ClientError({
      message: error.message,
      reason,
      status: error.status,
      ...(error.code ? { code: error.code } : {}),
    })
  }
  return new ClientError({
    message: error instanceof globalThis.Error ? error.message : "Browser Control request failed",
    reason,
  })
}

import { Data } from "effect"
import type { CdpEvent, JsonObject } from "./protocol.ts"
import type { ChildTarget, ConnectedTarget } from "./relay-types.ts"

type ClientCdpSessionAlias = Data.TaggedEnum<{
  Browser: {}
  Target: { readonly tabId: number; readonly targetId: string; readonly chromeSessionId?: string }
}>
export const ClientCdpSessionAlias = Data.taggedEnum<ClientCdpSessionAlias>()

type AnnouncedTarget = {
  readonly tabId: number
  readonly targetId: string
  readonly sessionId: string
  readonly parentSessionId?: string
}

type CdpClientState = {
  readonly aliases: Map<string, ClientCdpSessionAlias>
  readonly announcements: Map<string, AnnouncedTarget>
  readonly browserControlSessionId?: string
  readonly kind: "raw" | "sandbox"
  autoAttachParams?: JsonObject
}

export class CdpClientPool<Client extends object> implements Iterable<Client> {
  private readonly states = new Map<Client, CdpClientState>()
  private nextAliasId = 1
  private connectionGeneration = 0

  constructor(
    private readonly send: (client: Client, event: CdpEvent) => void,
    /** Observe every canonical session this client stops seeing, announced or silent. */
    private readonly retired: (client: Client, sessionId: string) => void,
  ) {}

  register(client: Client, browserControlSessionId?: string, kind: "raw" | "sandbox" = "raw"): void {
    if (this.states.has(client)) throw new Error("CDP client is already registered")
    this.states.set(client, {
      aliases: new Map(),
      announcements: new Map(),
      kind: browserControlSessionId ? kind : "raw",
      ...(browserControlSessionId ? { browserControlSessionId } : {}),
    })
    this.connectionGeneration += 1
  }

  unregister(client: Client): number | undefined {
    if (!this.states.delete(client) || this.states.size !== 0) return undefined
    return ++this.connectionGeneration
  }

  get size(): number {
    return this.states.size
  }

  has(client: Client): boolean {
    return this.states.has(client)
  }

  [Symbol.iterator](): IterableIterator<Client> {
    return this.states.keys()
  }

  sessionId(client: Client): string | undefined {
    return this.states.get(client)?.browserControlSessionId
  }

  isSandbox(client: Client): boolean {
    return this.states.get(client)?.kind === "sandbox"
  }

  hasSession(client: Client, sessionId: string): boolean {
    return this.states.get(client)?.announcements.has(sessionId) ?? false
  }

  announce(client: Client, target: ConnectedTarget | ChildTarget): void {
    const state = this.requireState(client)
    const targetId = target.targetInfo.targetId
    const existing = Array.from(state.announcements.values()).find((entry) => entry.targetId === targetId)
    if (existing?.sessionId === target.sessionId) return
    if (existing) this.detachSession(client, state, existing.sessionId)
    this.detachSession(client, state, target.sessionId)
    const parent = "parentSessionId" in target ? { parentSessionId: target.parentSessionId } : {}
    state.announcements.set(target.sessionId, { tabId: target.tabId, targetId, sessionId: target.sessionId, ...parent })
    this.send(client, {
      ...(parent.parentSessionId === undefined ? {} : { sessionId: parent.parentSessionId }),
      method: "Target.attachedToTarget",
      params: {
        sessionId: target.sessionId,
        targetInfo: { ...target.targetInfo, attached: true },
        waitingForDebugger: "waitingForDebugger" in target ? target.waitingForDebugger : false,
      },
    })
  }

  detach(client: Client, sessionId: string): void {
    const state = this.requireState(client)
    if (state.aliases.delete(sessionId)) return
    this.detachSession(client, state, sessionId, { notify: false })
  }

  detachTab(tabId: number, options: { readonly destroyed?: boolean } = {}): void {
    for (const [client, state] of this.states) {
      this.removeTargetAliases(state, (alias) => alias.tabId === tabId)
      for (const announced of state.announcements.values()) {
        if (announced.tabId === tabId) this.detachSession(client, state, announced.sessionId, options)
      }
    }
  }

  detachTarget(target: ChildTarget, options: { readonly notify?: boolean } = {}): void {
    for (const [client, state] of this.states) {
      this.removeTargetAliases(state, (alias) => alias.targetId === target.targetInfo.targetId)
      this.detachSession(client, state, target.sessionId, options)
    }
  }

  pruneInvisible(client: Client, canSeeTab: (tabId: number) => boolean): void {
    const state = this.requireState(client)
    this.removeTargetAliases(state, (alias) => !canSeeTab(alias.tabId))
    for (const announced of state.announcements.values()) {
      if (!canSeeTab(announced.tabId)) this.detachSession(client, state, announced.sessionId)
    }
  }

  sendToViewers(rootSessionId: string, event: CdpEvent, canSeeTab: (client: Client, tabId: number) => boolean): void {
    for (const [client, state] of this.states) {
      const announced = state.announcements.get(rootSessionId)
      if (!announced) continue
      if (!canSeeTab(client, announced.tabId)) {
        this.pruneInvisible(client, (tabId) => canSeeTab(client, tabId))
        continue
      }
      this.send(client, event)
      if (event.method.startsWith("Fetch.") || event.method === "Runtime.bindingCalled") {
        const isRootEvent = event.sessionId === undefined || event.sessionId === rootSessionId
        for (const [aliasId, alias] of state.aliases) {
          if (!ClientCdpSessionAlias.$is("Target")(alias) || alias.tabId !== announced.tabId) continue
          if (alias.chromeSessionId !== undefined ? alias.chromeSessionId === event.sessionId : isRootEvent) {
            this.send(client, { ...event, sessionId: aliasId })
          }
        }
      }
    }
  }

  setAutoAttachParams(client: Client, params: JsonObject | undefined): void {
    const state = this.requireState(client)
    if (params === undefined) delete state.autoAttachParams
    else state.autoAttachParams = params
  }

  autoAttachParams(client: Client): JsonObject | undefined {
    return this.states.get(client)?.autoAttachParams
  }

  isCurrentIdleGeneration(generation: number): boolean {
    return this.states.size === 0 && this.connectionGeneration === generation
  }

  createBrowserAlias(client: Client): string {
    const aliasId = this.nextAlias("browser")
    this.requireState(client).aliases.set(aliasId, ClientCdpSessionAlias.Browser())
    return aliasId
  }

  createTargetAlias(client: Client, target: ConnectedTarget | ChildTarget): string {
    const aliasId = this.nextAlias("session")
    this.requireState(client).aliases.set(aliasId, ClientCdpSessionAlias.Target({
      tabId: target.tabId,
      targetId: target.targetInfo.targetId,
      ...("parentSessionId" in target ? { chromeSessionId: target.sessionId } : {}),
    }))
    return aliasId
  }

  alias(client: Client, aliasId: string): ClientCdpSessionAlias | undefined {
    return this.states.get(client)?.aliases.get(aliasId)
  }

  private detachSession(client: Client, state: CdpClientState, sessionId: string, options: {
    readonly notify?: boolean
    readonly destroyed?: boolean
  } = {}): void {
    const announced = state.announcements.get(sessionId)
    if (!announced) return
    state.announcements.delete(sessionId)
    this.removeTargetAliases(state, (alias) => alias.targetId === announced.targetId)
    // Descendants must disappear before their parent, including on replacement.
    for (const child of state.announcements.values()) {
      if (child.parentSessionId === sessionId) this.detachSession(client, state, child.sessionId, options)
    }
    this.retired(client, sessionId)
    if (options.notify === false) return
    if (options.destroyed && announced.parentSessionId === undefined) {
      this.send(client, { method: "Target.targetDestroyed", params: { targetId: announced.targetId } })
    }
    this.send(client, {
      ...(announced.parentSessionId === undefined ? {} : { sessionId: announced.parentSessionId }),
      method: "Target.detachedFromTarget",
      params: { sessionId, targetId: announced.targetId },
    })
  }

  private removeTargetAliases(state: CdpClientState, matches: (alias: Data.TaggedEnum.Value<ClientCdpSessionAlias, "Target">) => boolean): void {
    for (const [aliasId, alias] of state.aliases) {
      if (ClientCdpSessionAlias.$is("Target")(alias) && matches(alias)) state.aliases.delete(aliasId)
    }
  }

  private nextAlias(kind: "browser" | "session"): string {
    return `bc-client-${kind}-${this.nextAliasId++}`
  }

  private requireState(client: Client): CdpClientState {
    const state = this.states.get(client)
    if (!state) throw new Error("CDP client is not registered")
    return state
  }
}

import { Deferred, Effect, Fiber, Predicate } from "effect"
import type { CdpRoutedSession } from "./cdp-router.ts"
import type { CdpEvent, JsonObject } from "./protocol.ts"
import { getNumber, getObject, getString } from "./relay-helpers.ts"
import { boundedToken, runtimeFailureKind } from "./runtime-diagnostics.ts"
import type { TargetRegistry } from "./target-registry.ts"

const maxCachedContexts = 512

type Waiter = {
  readonly sessionId: string
  readonly ready: Deferred.Deferred<boolean>
  readonly nativeReady: (event: CdpEvent) => boolean
  /** Installed once the enable command succeeds. */
  replay?: () => boolean
}

type Contexts = Map<number, CdpEvent>
/** `contexts` is undefined once the cache overflowed and can no longer prove completeness. */
type ContextCache = { readonly current: () => boolean; contexts: Contexts | undefined }
type Requester = {
  readonly current: () => boolean
  readonly delivered: Map<number, string | undefined>
  frameId?: string
}

const routeSessionId = (route: CdpRoutedSession) => route.chromeSessionId ?? route.rootSessionId
const disableKey = (tabId: number, chromeSessionId?: string) => `${tabId}:${chromeSessionId ?? "root"}`
const contextAux = (event: CdpEvent) => getObject(getObject(event.params?.context)?.auxData)

export class CdpRuntime<Client extends object> {
  private readonly waiters = new Set<Waiter>()
  private readonly contexts = new Map<string, ContextCache>()
  private readonly requesters = new WeakMap<Client, Map<string, Requester>>()
  private readonly disabling = new Map<string, number>()

  constructor(private readonly options: {
    readonly registry: TargetRegistry
    readonly generation: () => number
    readonly send: (command: { readonly tabId: number; readonly sessionId?: string; readonly method: string; readonly params: JsonObject }) => Effect.Effect<JsonObject, Error>
    readonly sendEvent: (client: Client, event: CdpEvent) => void
    readonly trace?: (message: string) => void
  }) {}

  notify(event: CdpEvent): void {
    if (event.sessionId) this.recordContextEvent(event.sessionId, event)
    if (event.method !== "Runtime.executionContextCreated" || contextAux(event)?.isDefault !== true) return
    // Replay missing sibling contexts before waking the native waiter: resolving
    // its Deferred can synchronously retire the waiter's pending replay.
    for (const waiter of this.waiters) this.settle(waiter)
    for (const waiter of this.waiters) {
      if (waiter.sessionId === event.sessionId && waiter.nativeReady(event)) Deferred.doneUnsafe(waiter.ready, Effect.succeed(true))
    }
  }

  /** Observe the exact events actually sent to this canonical client. Aliases never enter here. */
  deliver(client: Client, event: CdpEvent): void {
    const requester = event.sessionId ? this.requesters.get(client)?.get(event.sessionId) : undefined
    const active = requester?.current() ? requester : undefined
    const context = getObject(event.params?.context)
    const id = getNumber(context, "id")
    const destroyedId = getNumber(event.params, "executionContextId")
    if (event.method === "Runtime.executionContextsCleared") active?.delivered.clear()
    if (event.method === "Runtime.executionContextDestroyed" && destroyedId !== undefined) {
      active?.delivered.delete(destroyedId)
    }
    if (event.method === "Runtime.executionContextCreated" && active?.frameId !== undefined && id !== undefined) {
      const unique = getString(context, "uniqueId")
      if (active.delivered.has(id) && active.delivered.get(id) === unique) return
      active.delivered.set(id, unique)
    }
    this.options.sendEvent(client, event)
  }

  /** Construct at request admission; invoke with the result only after its successful response is sent. */
  frameTreeResponse(client: Client, route: CdpRoutedSession, canContinue: () => boolean): (result: unknown) => void {
    const requester = this.requester(client, route, canContinue)
    return (result) => {
      const frameId = getString(getObject(getObject(getObject(result)?.frameTree)?.frame), "id")
      if (!Predicate.isString(frameId) || !requester.current()) return
      requester.frameId = frameId
      for (const waiter of this.waiters) this.settle(waiter)
    }
  }

  disconnect(client: Client): void {
    this.requesters.delete(client)
  }

  detach(client: Client, sessionId: string): void {
    this.requesters.get(client)?.delete(sessionId)
  }

  beginDisable(tabId: number, chromeSessionId?: string): () => void {
    const key = disableKey(tabId, chromeSessionId)
    this.disabling.set(key, (this.disabling.get(key) ?? 0) + 1)
    this.invalidate(tabId, chromeSessionId)
    return () => {
      const count = (this.disabling.get(key) ?? 1) - 1
      if (count === 0) this.disabling.delete(key)
      else this.disabling.set(key, count)
    }
  }

  private recordContextEvent(sessionId: string, event: CdpEvent): void {
    if (!event.method.startsWith("Runtime.executionContext") && event.method !== "Page.frameDetached") return
    const cache = this.cacheFor(sessionId)
    if (!cache) return
    switch (event.method) {
      case "Runtime.executionContextsCleared":
        cache.contexts = new Map()
        return
      case "Runtime.executionContextDestroyed": {
        const id = getNumber(event.params, "executionContextId")
        if (id !== undefined) cache.contexts?.delete(id)
        return
      }
      case "Page.frameDetached":
        for (const [id, created] of cache.contexts ?? []) {
          if (contextAux(created)?.frameId === event.params?.frameId) cache.contexts?.delete(id)
        }
        return
      case "Runtime.executionContextCreated": {
        const id = getNumber(getObject(event.params?.context), "id")
        if (!cache.contexts || id === undefined) return
        cache.contexts.set(id, event)
        if (cache.contexts.size > maxCachedContexts) cache.contexts = undefined
      }
    }
  }

  private invalidate(tabId: number, chromeSessionId?: string): void {
    for (const [sessionId] of this.contexts) {
      const target = this.options.registry.targets.get(sessionId) ?? this.options.registry.childTargets.get(sessionId)
      if (target?.tabId === tabId && (chromeSessionId === undefined || sessionId === chromeSessionId)) this.contexts.delete(sessionId)
    }
  }

  private cacheFor(sessionId: string): ContextCache | undefined {
    for (const [key, value] of this.contexts) if (!value.current()) this.contexts.delete(key)
    const root = this.options.registry.targets.get(sessionId)
    const child = this.options.registry.childTargets.get(sessionId)
    const parent = child ? this.options.registry.tabTargets.get(child.tabId) : undefined
    const route = root ? { tabId: root.tabId, rootSessionId: root.sessionId }
      : child && parent ? { tabId: child.tabId, rootSessionId: parent.sessionId, chromeSessionId: child.sessionId } : undefined
    if (!route) return undefined
    if (this.disabling.has(disableKey(route.tabId)) || this.disabling.has(disableKey(route.tabId, route.chromeSessionId))) return undefined
    let cache = this.contexts.get(sessionId)
    if (!cache) {
      cache = { current: this.capture(route), contexts: new Map() }
      this.contexts.set(sessionId, cache)
    }
    return cache
  }

  private requester(client: Client, route: CdpRoutedSession, canContinue: () => boolean): Requester {
    const sessions = this.requesters.get(client) ?? new Map<string, Requester>()
    this.requesters.set(client, sessions)
    const sessionId = routeSessionId(route)
    const existing = sessions.get(sessionId)
    if (existing?.current()) return existing
    const captured = this.capture(route)
    const next: Requester = {
      current: () => captured() && canContinue() && this.requesters.get(client) === sessions && sessions.get(sessionId) === next,
      delivered: new Map(),
    }
    sessions.set(sessionId, next)
    return next
  }

  readonly enable = Effect.fn("CdpRuntime.enable")(function* (
    this: CdpRuntime<Client>,
    route: CdpRoutedSession,
    params: JsonObject,
    canContinue: () => boolean,
    client?: Client,
  ) {
    const current = this.capture(route)
    const permitted = () => current() && canContinue()
    // Raw CDP clients need not request a frame tree. Preserve their ordinary
    // native-event path; cached replay requires a frame-tree request already admitted.
    const requester = client ? this.requesters.get(client)?.get(routeSessionId(route)) : undefined
    const rootFrame = () => requester && permitted() && requester.current() ? requester.frameId : undefined
    const first = yield* this.observe(route, Effect.suspend(() => permitted()
      ? this.options.send({
        tabId: route.tabId, method: "Runtime.enable", params,
        ...(route.chromeSessionId === undefined ? {} : { sessionId: route.chromeSessionId }),
      })
      : Effect.fail(new Error("CDP target changed before Runtime.enable"))), client && requester ? {
      replay: () => {
        const frameId = rootFrame()
        return frameId !== undefined && this.replayCached(client, route, frameId)
      },
      nativeReady: (event) => {
        const frameId = rootFrame()
        return frameId !== undefined && contextAux(event)?.frameId === frameId
      },
    } : {})
    this.trace(route, `runtime-enable defaultContextSeen=${first.seen}`)
    if (!first.seen && permitted()) {
      // The shared debugger may acknowledge enable without replaying its context.
      // Never run the recovery cycle against a successor generation or new owner.
      const retry = yield* this.observe(route, this.reset(route, "Runtime.disable", {}, permitted).pipe(
        Effect.andThen(() => this.reset(route, "Runtime.enable", params, permitted)),
      ))
      this.trace(route, `runtime-reset phase=missing-default-context defaultContextSeen=${retry.seen}`)
    }
    return first.result
  })

  readonly disableIdle = Effect.fn("CdpRuntime.disableIdle")(function* (this: CdpRuntime<Client>, stillIdle: () => boolean) {
    const { registry } = this.options
    const routes: CdpRoutedSession[] = registry.listRootTargets().map((target) => ({ tabId: target.tabId, rootSessionId: target.sessionId }))
    for (const target of registry.childTargets.values()) {
      const root = registry.tabTargets.get(target.tabId)
      if (root) routes.push({ tabId: target.tabId, rootSessionId: root.sessionId, chromeSessionId: target.sessionId })
    }
    const targets = routes.map((route) => ({ route, current: this.capture(route) }))
    for (const { route, current } of targets) {
      if (!stillIdle()) break
      yield* this.reset(route, "Runtime.disable", {}, () => stillIdle() && current())
    }
  })

  /** Replay a complete cache only when it already holds the requester's root-frame default context. */
  private replayCached(client: Client, route: CdpRoutedSession, frameId: string): boolean {
    const cache = this.contexts.get(routeSessionId(route))
    const contexts = cache?.current() ? cache.contexts : undefined
    if (!contexts || ![...contexts.values()].some((event) => {
      const aux = contextAux(event)
      return aux?.isDefault === true && aux.frameId === frameId
    })) return false
    for (const event of contexts.values()) this.deliver(client, event)
    this.trace(route, "runtime-replay defaultContextSeen=true")
    return true
  }

  private settle(waiter: Waiter): void {
    if (waiter.replay?.()) Deferred.doneUnsafe(waiter.ready, Effect.succeed(true))
  }

  private observe<A>(route: CdpRoutedSession, command: Effect.Effect<A, Error>, options: {
    readonly replay?: () => boolean
    readonly nativeReady?: (event: CdpEvent) => boolean
  } = {}): Effect.Effect<{ readonly result: A; readonly seen: boolean }, Error> {
    const runtime = this
    return Effect.acquireUseRelease(
      Effect.sync(() => {
        const waiter: Waiter = { sessionId: routeSessionId(route), ready: Deferred.makeUnsafe(), nativeReady: options.nativeReady ?? (() => true) }
        runtime.waiters.add(waiter)
        return waiter
      }),
      (waiter) => Effect.gen(function* () {
        // Start the window before sending: context events may precede the reply.
        const seen = yield* Effect.forkScoped(Deferred.await(waiter.ready).pipe(Effect.timeoutOrElse({
          duration: "3 seconds",
          orElse: () => Effect.succeed(false),
        })), { startImmediately: true })
        const result = yield* command
        if (options.replay) waiter.replay = options.replay
        runtime.settle(waiter)
        return { result, seen: yield* Fiber.join(seen) }
      }).pipe(Effect.scoped),
      (waiter) => Effect.sync(() => { runtime.waiters.delete(waiter) }),
    )
  }

  private reset(route: CdpRoutedSession, method: "Runtime.enable" | "Runtime.disable", params: JsonObject, current: () => boolean): Effect.Effect<void> {
    return Effect.suspend(() => {
      if (!current()) return Effect.void
      this.trace(route, `runtime-reset command=${method}`)
      return this.options.send({ tabId: route.tabId, method, params, ...(route.chromeSessionId === undefined ? {} : { sessionId: route.chromeSessionId }) }).pipe(
        Effect.match({
          onFailure: (error) => this.trace(route, `runtime-reset command=${method} outcome=failed failure=${runtimeFailureKind(error)}`),
          onSuccess: () => this.trace(route, `runtime-reset command=${method} outcome=ok`),
        }),
      )
    })
  }

  private capture(route: CdpRoutedSession): () => boolean {
    const { registry } = this.options
    const generation = this.options.generation()
    const root = registry.targets.get(route.rootSessionId)
    const owner = root?.browserControlSessionId
    const child = route.chromeSessionId === undefined ? undefined : registry.childTargets.get(route.chromeSessionId)
    return () => {
      const currentRoot = registry.routingRootTarget(route.tabId)
      if (!root || generation !== this.options.generation() || currentRoot?.sessionId !== root.sessionId || currentRoot.targetInfo.targetId !== root.targetInfo.targetId || currentRoot.browserControlSessionId !== owner) return false
      if (route.chromeSessionId === undefined) return true
      const currentChild = registry.childTargets.get(route.chromeSessionId)
      return child !== undefined && currentChild?.tabId === route.tabId && currentChild.targetInfo.targetId === child.targetInfo.targetId && currentChild.parentSessionId === child.parentSessionId
    }
  }

  private trace(route: CdpRoutedSession, message: string): void {
    this.options.trace?.(`${message} tab=${route.tabId} rootSession=${boundedToken(route.rootSessionId)} chromeSession=${boundedToken(route.chromeSessionId)}`)
  }
}

import fs from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { afterEach, describe, expect, it } from "vitest"
import { Effect } from "effect"
import * as AuthProfile from "../src/auth-profile.ts"
import { SecretProfile } from "../src/index.ts"

const temporaryDirectories: string[] = []

afterEach(async () => {
  await Promise.all(temporaryDirectories.splice(0).map((directory) => fs.rm(directory, { recursive: true, force: true })))
})

describe("AuthProfile", () => {
  it("writes restrictive profiles and returns metadata without values", async () => {
    const baseDir = await temporaryDirectory()
    const result = await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "token-value", sources: ["request.header.authorization"] }],
    }))

    expect(result).toMatchObject({ name: "uber", slotCount: 1, slots: [{ ref: "BC_SECRET_1", expired: false }] })
    expect(JSON.stringify(result)).not.toContain("token-value")
    const publicStatus = await Effect.runPromise(SecretProfile.status("uber", { baseDir }))
    expect(publicStatus).toEqual(result)
    const stat = await fs.stat(path.join(baseDir, "uber.json"))
    expect(stat.mode & 0o777).toBe(0o600)
  })

  it("injects profile values and redacts them from child output", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "token-value", sources: ["request.header.authorization"] }],
    }))

    const result = await Effect.runPromise(SecretProfile.run({
      name: "uber",
      baseDir,
      command: process.execPath,
      args: ["-e", "process.stdout.write(process.env.BC_SECRET_1 || '')"],
    }))
    expect(result).toMatchObject({ exitCode: 0, stdout: "${BC_SECRET_1}", stderr: "" })
  })

  it("exposes a runtime error class and rejects unsafe worker bounds", async () => {
    const baseDir = await temporaryDirectory()

    await expect(Effect.runPromise(SecretProfile.run({
      name: "uber",
      baseDir,
      command: process.execPath,
      timeoutMs: 0,
    }))).rejects.toBeInstanceOf(SecretProfile.Error)
    await expect(Effect.runPromise(SecretProfile.run({
      name: "uber",
      baseDir,
      command: process.execPath,
      maxOutputBytes: -1,
    }))).rejects.toMatchObject({ _tag: "AuthProfile.Error", reason: "run-failed" })
  })

  it("does not leak a credential cut by the output budget", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "long-token-value", sources: ["request.header.authorization"] }],
    }))

    const result = await Effect.runPromise(AuthProfile.run({
      name: "uber",
      baseDir,
      maxOutputBytes: 8,
      command: process.execPath,
      args: ["-e", "process.stdout.write(process.env.BC_SECRET_1 || '')"],
    }))
    expect(result.stdout).toBe("")
    expect(result.stdoutTruncated).toBe(true)
  })

  it("updates an existing profile without changing its creation time", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "old", sources: ["request.header.authorization"] }],
    }))
    const before = await Effect.runPromise(AuthProfile.read("uber", { baseDir }))
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "new", sources: ["request.header.authorization"] }],
    }))
    const after = await Effect.runPromise(AuthProfile.read("uber", { baseDir }))

    expect(after.createdAt).toBe(before.createdAt)
    expect(after.slots[0]?.value).toBe("new")
  })

  it("does not overwrite a malformed existing profile", async () => {
    const baseDir = await temporaryDirectory()
    const filePath = path.join(baseDir, "uber.json")
    await fs.writeFile(filePath, "not-json", { mode: 0o600 })

    await expect(Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "new", sources: ["request.header.authorization"] }],
    }))).rejects.toMatchObject({ _tag: "AuthProfile.Error", reason: "invalid-json" })
    await expect(fs.readFile(filePath, "utf8")).resolves.toBe("not-json")
  })

  it("terminates a timed-out credential-bearing process", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "token-value", sources: ["request.header.authorization"] }],
    }))

    const result = await Effect.runPromise(AuthProfile.run({
      name: "uber",
      baseDir,
      timeoutMs: 20,
      command: process.execPath,
      args: ["-e", "setInterval(() => {}, 1000)"],
    }))
    expect(result.exitCode).toBe(1)
    expect(result.signal).toMatch(/SIGTERM|SIGKILL/)
  })

  it("does not pass inherited Browser Control secret slots to the child", async () => {
    const baseDir = await temporaryDirectory()
    await Effect.runPromise(AuthProfile.write({
      name: "uber",
      baseDir,
      slots: [{ ref: "BC_SECRET_1", value: "profile-token", sources: ["request.header.authorization"] }],
    }))
    process.env.BC_SECRET_999 = "<REDACTED>"
    try {
      const result = await Effect.runPromise(AuthProfile.run({
        name: "uber",
        baseDir,
        command: process.execPath,
        args: ["-e", "process.stdout.write(process.env.BC_SECRET_999 || '')"],
      }))
      expect(result.stdout).toBe("")
    } finally {
      delete process.env.BC_SECRET_999
    }
  })

  it("serializes profile transactions through a filesystem lock", async () => {
    const baseDir = await temporaryDirectory()
    let active = 0
    let maximumActive = 0
    const transaction = () => AuthProfile.withLock("uber", { baseDir }, Effect.gen(function* () {
      active += 1
      maximumActive = Math.max(maximumActive, active)
      yield* Effect.sleep(30)
      active -= 1
    }))

    await Promise.all([Effect.runPromise(transaction()), Effect.runPromise(transaction())])
    expect(maximumActive).toBe(1)
    await expect(fs.stat(path.join(baseDir, "uber.json.lock"))).rejects.toMatchObject({ code: "ENOENT" })
  })
})

async function temporaryDirectory(): Promise<string> {
  const directory = await fs.mkdtemp(path.join(os.tmpdir(), "browser-control-auth-"))
  temporaryDirectories.push(directory)
  return directory
}

import { describe, expect, it } from "vitest"
import { guardCdpMethod } from "../src/cdp-guardrails.ts"

describe("cdp-guardrails", () => {
  it("always blocks browser-state-destroying methods", () => {
    for (const method of ["Network.clearBrowserCookies", "Network.clearBrowserCache", "Storage.clearCookies", "Browser.close"]) {
      const message = guardCdpMethod({ method, readOnly: false })
      expect(message).toContain(`Browser Control blocked ${method}`)
      expect(message).toContain("always blocked")
    }
  })

  it("allows ordinary methods", () => {
    for (const method of ["Page.navigate", "Runtime.evaluate", "Target.createTarget", "Network.enable", "Input.dispatchMouseEvent"]) {
      expect(guardCdpMethod({ method, readOnly: false })).toBeNull()
    }
  })

  it("blocks input dispatch for read-only sessions with the session id in the message", () => {
    const message = guardCdpMethod({ method: "Input.dispatchMouseEvent", readOnly: true, sessionId: "quiet-owl-1" })
    expect(message).toContain("Session quiet-owl-1 is read-only")
    expect(message).toContain("Input.dispatchMouseEvent")
  })

  it("blocks all Input.* methods in read-only mode but allows reads", () => {
    expect(guardCdpMethod({ method: "Input.dispatchKeyEvent", readOnly: true })).not.toBeNull()
    expect(guardCdpMethod({ method: "Input.insertText", readOnly: true })).not.toBeNull()
    expect(guardCdpMethod({ method: "Runtime.evaluate", readOnly: true })).toBeNull()
    expect(guardCdpMethod({ method: "Page.captureScreenshot", readOnly: true })).toBeNull()
  })
})

import { describe, expect, it } from "vitest"
import { CdpClientPool } from "../src/cdp-client-pool.ts"
import { CdpRouter, isRootRoutableBrowserContextMethod } from "../src/cdp-router.ts"
import type { CdpEvent } from "../src/protocol.ts"
import type { ChildTarget, ConnectedTarget } from "../src/relay-types.ts"
import { TargetRegistry } from "../src/target-registry.ts"

function root(options: {
  readonly tabId: number
  readonly sessionId: string
  readonly targetId: string
  readonly browserControlSessionId?: string
  readonly browserContextId?: string
  readonly owner?: "relay" | "user"
  readonly crashed?: boolean
}): ConnectedTarget {
  return {
    tabId: options.tabId,
    sessionId: options.sessionId,
    targetInfo: {
      targetId: options.targetId,
      type: "page",
      title: options.targetId,
      url: `https://example.com/${options.targetId}`,
      attached: true,
      canAccessOpener: false,
      ...(options.browserContextId ? { browserContextId: options.browserContextId } : {}),
    },
    owner: options.owner ?? "relay",
    ...(options.browserControlSessionId ? { browserControlSessionId: options.browserControlSessionId } : {}),
    ...(options.crashed ? { crashed: true } : {}),
  }
}

function setup() {
  const events: { client: object; event: CdpEvent }[] = []
  const clients = new CdpClientPool<object>((client, event) => events.push({ client, event }), () => {})
  const registry = new TargetRegistry()
  const router = new CdpRouter(clients, registry)
  return { clients, registry, router, events }
}

describe("CdpRouter", () => {
  it("does not reinterpret a disconnected client as a raw client", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    registry.addRootTarget(root({ tabId: 1, sessionId: "root", targetId: "target", owner: "user" }))
    expect(router.session(client, "root")).toBeDefined()
    clients.unregister(client)
    expect(router.session(client, "root")).toBeUndefined()
    expect(router.visibleTargetInfos(client)).toEqual([])
  })
  it("classifies browser-context methods that Chrome routes through a root tab", () => {
    for (const method of [
      "Browser.grantPermissions",
      "Browser.resetPermissions",
      "Storage.getCookies",
      "Storage.setCookies",
      "Storage.clearCookies",
    ]) {
      expect(isRootRoutableBrowserContextMethod(method)).toBe(true)
    }
    expect(isRootRoutableBrowserContextMethod("Runtime.evaluate")).toBe(false)
  })

  it("prefers a session-owned root for a named client", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    const owned = root({
      tabId: 1,
      sessionId: "owned-root",
      targetId: "owned-target",
      browserControlSessionId: "session-a",
    })
    registry.addRootTarget(owned)
    registry.addRootTarget(root({
      tabId: 2,
      sessionId: "unrelated-root",
      targetId: "unrelated-target",
      owner: "user",
    }))

    expect(router.preferredRoot(client)).toBe(owned)

    registry.addRootTarget(root({
      tabId: 3,
      sessionId: "second-owned-root",
      targetId: "second-owned-target",
      browserControlSessionId: "session-a",
    }))
    expect(router.preferredRoot(client)).toBe(owned)
  })

  it("recognizes browser session aliases", () => {
    const { clients, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    const browserAlias = clients.createBrowserAlias(client)

    expect(router.isBrowserAlias(client, browserAlias)).toBe(true)
    expect(router.isBrowserAlias(client, "unknown-session")).toBe(false)
  })

  it("skips a crashed owned root that precedes a healthy sibling", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    registry.addRootTarget(root({ tabId: 1, sessionId: "crashed-root", targetId: "crashed-target", browserControlSessionId: "session-a" }))
    registry.markRootTargetCrashed(1)
    const healthy = root({ tabId: 2, sessionId: "healthy-root", targetId: "healthy-target", browserControlSessionId: "session-a" })
    registry.addRootTarget(healthy)

    expect(registry.listRootTargets().map((target) => target.tabId)).toEqual([1, 2])
    expect(router.preferredRoot(client)).toBe(healthy)
    expect(router.visibleRoots(client)).toHaveLength(2)
    expect(router.session(client, "crashed-root")).toEqual({ tabId: 1, rootSessionId: "crashed-root" })
  })

  it("does not replace crashed owned roots with an unrelated healthy root", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    for (const tabId of [1, 2]) {
      registry.addRootTarget(root({ tabId, sessionId: `root-${tabId}`, targetId: `target-${tabId}`, browserControlSessionId: "session-a" }))
      registry.markRootTargetCrashed(tabId)
    }
    registry.addRootTarget(root({ tabId: 3, sessionId: "unrelated-root", targetId: "unrelated-target", owner: "user" }))

    expect(router.preferredRoot(client)).toBeUndefined()
  })

  it("does not fall through from an empty named session to an unrelated root", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    registry.addRootTarget(root({
      tabId: 1,
      sessionId: "unrelated-root",
      targetId: "unrelated-target",
    }))

    expect(router.visibleRoots(client)).toHaveLength(1)
    expect(router.preferredRoot(client)).toBeUndefined()
  })

  it("groups raw roots in the default browser context", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    const visible = root({ tabId: 1, sessionId: "root-1", targetId: "target-1" })
    registry.addRootTarget(visible)

    expect(router.preferredRoot(client)).toBe(visible)

    registry.addRootTarget(root({ tabId: 2, sessionId: "root-2", targetId: "target-2" }))
    expect(router.preferredRoot(client)).toBe(visible)
  })

  it("groups multiple raw roots only when they prove the same browser context", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    const first = root({ tabId: 1, sessionId: "root-1", targetId: "target-1", browserContextId: "context-a" })
    registry.addRootTarget(first)
    registry.addRootTarget(root({ tabId: 2, sessionId: "root-2", targetId: "target-2", browserContextId: "context-a" }))
    expect(router.preferredRoot(client)).toBe(first)

    registry.addRootTarget(root({ tabId: 3, sessionId: "root-3", targetId: "target-3", browserContextId: "context-b" }))
    expect(router.preferredRoot(client)).toBeUndefined()
    expect(router.preferredRoot(client, "context-a")).toBe(first)
    expect(router.preferredRoot(client, "missing-context")).toBeUndefined()
  })

  it("validates context identity and skips crashed roots for named clients", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    registry.addRootTarget(root({
      tabId: 1,
      sessionId: "crashed-root",
      targetId: "crashed-target",
      browserControlSessionId: "session-a",
      browserContextId: "context-a",
      crashed: true,
    }))
    const healthy = root({
      tabId: 2,
      sessionId: "healthy-root",
      targetId: "healthy-target",
      browserControlSessionId: "session-a",
      browserContextId: "context-a",
    })
    registry.addRootTarget(healthy)
    registry.addRootTarget(root({
      tabId: 3,
      sessionId: "other-context-root",
      targetId: "other-context-target",
      browserControlSessionId: "session-a",
      browserContextId: "context-b",
    }))

    expect(router.preferredRoot(client)).toBe(healthy)
    expect(router.preferredRoot(client, "context-a")).toBe(healthy)
    expect(router.preferredRoot(client, "context-b")?.tabId).toBe(3)
    expect(router.preferredRoot(client, "context-missing")).toBeUndefined()
  })

  it("excludes crashed roots from raw context routing while keeping explicit access", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    registry.addRootTarget(root({ tabId: 1, sessionId: "root-1", targetId: "target-1" }))
    const crashed = registry.markRootTargetCrashed(1)
    expect(router.preferredRoot(client)).toBeUndefined()
    expect(router.targetForAttach(client, "target-1")).toBe(crashed)

    const healthy = root({ tabId: 2, sessionId: "root-2", targetId: "target-2" })
    registry.addRootTarget(healthy)
    expect(router.preferredRoot(client)).toBe(healthy)
  })

  it("resolves only targets visible to the client", () => {
    const { clients, registry, router } = setup()
    const owner = {}
    const other = {}
    clients.register(owner, "session-a")
    clients.register(other, "session-b")
    const target = root({
      tabId: 1,
      sessionId: "bc-tab-1",
      targetId: "target-1",
      browserControlSessionId: "session-a",
    })
    registry.addRootTarget(target)

    expect(router.targetForAttach(owner, "target-1")).toBe(target)
    expect(router.targetInfo(owner, { sessionId: "bc-tab-1" })).toBe(target)
    expect(router.targetForAttach(other, "target-1")).toBeUndefined()
    expect(router.targetInfo(other, { targetId: "target-1" })).toBeUndefined()
  })

  it("routes root aliases without a Chrome session and child aliases with one", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    const target = root({ tabId: 1, sessionId: "bc-tab-1", targetId: "target-1" })
    registry.addRootTarget(target)
    const child: ChildTarget = {
      tabId: 1,
      sessionId: "child-session",
      parentSessionId: target.sessionId,
      targetInfo: { ...target.targetInfo, targetId: "child-target", type: "iframe" },
      waitingForDebugger: false,
    }
    registry.addChildTarget(child)
    const rootAlias = clients.createTargetAlias(client, target)
    const childAlias = clients.createTargetAlias(client, child)

    expect(router.session(client, rootAlias)).toEqual({ tabId: 1, rootSessionId: "bc-tab-1" })
    expect(router.session(client, childAlias)).toEqual({
      tabId: 1,
      rootSessionId: "bc-tab-1",
      chromeSessionId: "child-session",
    })
  })

  it("does not resolve identity-free or hidden session routes", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-b")
    registry.addRootTarget(root({
      tabId: 1,
      sessionId: "bc-tab-1",
      targetId: "target-1",
      browserControlSessionId: "session-a",
    }))

    expect(router.targetInfo(client, {})).toBeUndefined()
    expect(router.session(client, "bc-tab-1")).toBeUndefined()
    expect(router.rootForSession(client, "bc-tab-1")).toBeUndefined()
  })

  it("rejects stale aliases and children without a live root", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client)
    const target = root({ tabId: 1, sessionId: "bc-tab-1", targetId: "target-1" })
    registry.addRootTarget(target)
    const alias = clients.createTargetAlias(client, target)

    registry.addRootTarget(root({ tabId: 1, sessionId: "bc-tab-2", targetId: "target-2" }))
    expect(router.session(client, alias)).toBeUndefined()

    registry.detachRootTargetState(1)
    const orphan: ChildTarget = {
      tabId: 1,
      sessionId: "orphan-session",
      parentSessionId: "bc-tab-missing",
      targetInfo: { ...target.targetInfo, targetId: "orphan-target", type: "iframe" },
      waitingForDebugger: false,
    }
    registry.addChildTarget(orphan)
    expect(router.targetForAttach(client, "orphan-target")).toBeUndefined()
    expect(router.session(client, "orphan-session")).toBeUndefined()
  })

  it("does not fall through from an explicit hidden target to a visible session", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    const visible = root({ tabId: 1, sessionId: "visible-session", targetId: "visible-target", browserControlSessionId: "session-a" })
    const hidden = root({ tabId: 2, sessionId: "hidden-session", targetId: "hidden-target", browserControlSessionId: "session-b" })
    registry.addRootTarget(visible)
    registry.addRootTarget(hidden)

    expect(router.targetInfo(client, {
      targetId: "hidden-target",
      sessionId: "visible-session",
    })).toBeUndefined()
  })

  it("prunes aliases when ownership hides a tab even without an announcement", () => {
    const { clients, registry, router, events } = setup()
    const client = {}
    clients.register(client, "session-a")
    const rawTarget = root({ tabId: 1, sessionId: "raw-session", targetId: "raw-target" })
    registry.addRootTarget(rawTarget)
    const alias = clients.createTargetAlias(client, rawTarget)
    const browserAlias = clients.createBrowserAlias(client)
    registry.addRootTarget(root({
      tabId: 2,
      sessionId: "owned-session",
      targetId: "owned-target",
      browserControlSessionId: "session-a",
    }))

    router.reconcileClient(client)

    expect(clients.alias(client, alias)).toBeUndefined()
    expect(router.isBrowserAlias(client, browserAlias)).toBe(true)
    expect(events).toEqual([])
  })

  it("reconciles announcements and aliases across ownership reservation and rollback", () => {
    const { clients, registry, router, events } = setup()
    const owner = { name: "owner" }
    const other = { name: "other" }
    const raw = { name: "raw" }
    clients.register(owner, "session-a")
    clients.register(other, "session-b")
    clients.register(raw)
    const target = root({ tabId: 1, sessionId: "user-root", targetId: "user-target", owner: "user" })
    const child: ChildTarget = {
      tabId: 1,
      sessionId: "user-child",
      parentSessionId: target.sessionId,
      targetInfo: { ...target.targetInfo, targetId: "child-target", type: "iframe" },
      waitingForDebugger: false,
    }
    const rawTarget = root({ tabId: 2, sessionId: "raw-root", targetId: "raw-target" })
    registry.addRootTarget(target)
    registry.addRootTarget(rawTarget)
    registry.addChildTarget(child)
    for (const client of clients) {
      expect(router.canSeeTarget(client, target)).toBe(true)
      clients.announce(client, target)
      clients.announce(client, child)
    }
    const ownerAlias = clients.createTargetAlias(owner, target)
    const otherAlias = clients.createTargetAlias(other, target)
    const otherChildAlias = clients.createTargetAlias(other, child)
    const rawAlias = clients.createTargetAlias(raw, target)
    const aliasOnly = clients.createTargetAlias(owner, rawTarget)
    const browserAlias = clients.createBrowserAlias(other)
    events.length = 0

    const reservation = registry.reserveTargetOwnership(target.targetInfo.targetId, "session-a")
    for (const client of clients) router.reconcileClient(client)

    const detached: CdpEvent[] = [
      {
        sessionId: target.sessionId,
        method: "Target.detachedFromTarget",
        params: { sessionId: child.sessionId, targetId: child.targetInfo.targetId },
      },
      {
        method: "Target.detachedFromTarget",
        params: { sessionId: target.sessionId, targetId: target.targetInfo.targetId },
      },
    ]
    expect(events).toEqual([
      ...detached.map((event) => ({ client: other, event })),
      ...detached.map((event) => ({ client: raw, event })),
    ])
    for (const client of [other, raw]) {
      expect(router.canSeeTab(client, target.tabId)).toBe(false)
      expect(clients.hasSession(client, target.sessionId)).toBe(false)
      expect(clients.hasSession(client, child.sessionId)).toBe(false)
      expect(router.session(client, target.sessionId)).toBeUndefined()
      expect(router.targetForAttach(client, child.targetInfo.targetId)).toBeUndefined()
    }
    expect(clients.alias(other, otherAlias)).toBeUndefined()
    expect(clients.alias(other, otherChildAlias)).toBeUndefined()
    expect(clients.alias(raw, rawAlias)).toBeUndefined()
    expect(clients.alias(owner, aliasOnly)).toBeUndefined()
    expect(router.isBrowserAlias(other, browserAlias)).toBe(true)
    expect(router.session(owner, ownerAlias)).toEqual({ tabId: 1, rootSessionId: target.sessionId })
    expect(clients.hasSession(owner, child.sessionId)).toBe(true)

    events.length = 0
    registry.rollbackTargetOwnership(reservation)
    for (const client of clients) router.reconcileClient(client)
    expect(events).toEqual([])
    for (const client of clients) expect(router.canSeeTab(client, target.tabId)).toBe(true)
    expect(router.canSeeTab(owner, rawTarget.tabId)).toBe(true)
    expect(clients.alias(owner, aliasOnly)).toBeUndefined()

    const event: CdpEvent = { sessionId: child.sessionId, method: "Runtime.executionContextsCleared", params: {} }
    clients.sendToViewers(target.sessionId, event, (client, tabId) => router.canSeeTab(client, tabId))
    expect(events).toEqual([{ client: owner, event }])

    events.length = 0
    for (const client of [other, raw]) {
      clients.announce(client, target)
      clients.announce(client, child)
      expect(clients.hasSession(client, target.sessionId)).toBe(true)
      expect(clients.hasSession(client, child.sessionId)).toBe(true)
    }
    expect(events.map(({ event }) => event.method)).toEqual([
      "Target.attachedToTarget",
      "Target.attachedToTarget",
      "Target.attachedToTarget",
      "Target.attachedToTarget",
    ])
    expect(router.session(other, otherAlias)).toBeUndefined()
    expect(router.session(other, otherChildAlias)).toBeUndefined()
    expect(router.session(raw, rawAlias)).toBeUndefined()
    const newAlias = clients.createTargetAlias(other, child)
    expect(router.session(other, newAlias)).toEqual({ tabId: 1, rootSessionId: target.sessionId, chromeSessionId: child.sessionId })
  })

  it("keeps real session routes alive after a client detaches only its alias", () => {
    const { clients, registry, router, events } = setup()
    const client = {}
    clients.register(client)
    const target = root({ tabId: 1, sessionId: "bc-tab-1", targetId: "target-1" })
    registry.addRootTarget(target)
    clients.announce(client, target)
    const alias = clients.createTargetAlias(client, target)
    events.length = 0

    clients.detach(client, alias)

    expect(router.session(client, alias)).toBeUndefined()
    expect(router.session(client, target.sessionId)).toEqual({ tabId: 1, rootSessionId: target.sessionId })
    expect(registry.getRootTargetByTabId(1)).toBe(target)
    expect(clients.hasSession(client, target.sessionId)).toBe(true)
    expect(events).toEqual([])
  })

  it("lists only visible roots and exposed children", () => {
    const { clients, registry, router } = setup()
    const client = {}
    clients.register(client, "session-a")
    const visible = root({ tabId: 1, sessionId: "bc-tab-1", targetId: "target-1", browserControlSessionId: "session-a" })
    const hidden = root({ tabId: 2, sessionId: "bc-tab-2", targetId: "target-2", browserControlSessionId: "session-b" })
    registry.addRootTarget(visible)
    registry.addRootTarget(hidden)
    registry.addChildTarget({
      tabId: 1,
      sessionId: "child-visible",
      parentSessionId: visible.sessionId,
      targetInfo: { ...visible.targetInfo, targetId: "child-visible-target", type: "worker" },
      waitingForDebugger: false,
    })
    registry.addChildTarget({
      tabId: 1,
      sessionId: "child-held",
      parentSessionId: visible.sessionId,
      targetInfo: { ...visible.targetInfo, targetId: "child-held-target", type: "page", url: "" },
      waitingForDebugger: false,
    })

    expect(router.visibleTargetInfos(client).map((target) => target.targetId)).toEqual(["target-1", "child-visible-target"])
  })
})

import fs from "node:fs/promises"
import http from "node:http"
import path from "node:path"
import { fileURLToPath } from "node:url"

/**
 * Two loopback origins serving gauntlet/fixtures. The secondary origin exists so
 * the payment iframe can be cross-site; everything else lives on the
 * primary origin. Ports are fixed by default so fixture URLs are stable across
 * runs and readable in relay status output.
 */
export type GauntletServers = {
  readonly primaryOrigin: string
  readonly secondaryOrigin: string
  readonly close: () => Promise<void>
}

export type GauntletServerOptions = {
  readonly primaryPort?: number
  readonly secondaryPort?: number
  readonly host?: string
  readonly stallKeepaliveMs?: number
}

const fixturesDirectory = path.join(path.dirname(fileURLToPath(import.meta.url)), "fixtures")
const secondaryOriginPlaceholder = "__SECONDARY_ORIGIN__"

export const defaultPrimaryPort = 19801
export const defaultSecondaryPort = 19802

export async function startGauntletServers(options: GauntletServerOptions = {}): Promise<GauntletServers> {
  const host = options.host ?? "127.0.0.1"
  const primaryPort = options.primaryPort ?? defaultPrimaryPort
  const secondaryPort = options.secondaryPort ?? defaultSecondaryPort
  // Different loopback ports alone are cross-origin, but still same-site.
  // localhost versus 127.0.0.1 lets an isolated --site-per-process browser prove
  // the OOPIF transport. Cases must still assert an actual iframe target.
  const secondaryOrigin = `http://${host === "127.0.0.1" ? "localhost" : host}:${secondaryPort}`
  const stallKeepaliveMs = options.stallKeepaliveMs ?? 5_000
  const openStalls = new Set<http.ServerResponse>()

  const primary = http.createServer((request, response) => {
    void handleRequest(request, response, { secondaryOrigin, stallKeepaliveMs, openStalls })
  })
  const secondary = http.createServer((request, response) => {
    void handleRequest(request, response, { secondaryOrigin, stallKeepaliveMs, openStalls })
  })

  await listen(primary, primaryPort, host)
  try {
    await listen(secondary, secondaryPort, host)
  } catch (error) {
    await closeServer(primary)
    throw error
  }

  return {
    primaryOrigin: `http://${host}:${primaryPort}`,
    secondaryOrigin,
    close: async () => {
      for (const response of openStalls) response.destroy()
      openStalls.clear()
      await Promise.all([closeServer(primary), closeServer(secondary)])
    },
  }
}

type RequestContext = {
  readonly secondaryOrigin: string
  readonly stallKeepaliveMs: number
  readonly openStalls: Set<http.ServerResponse>
}

async function handleRequest(request: http.IncomingMessage, response: http.ServerResponse, context: RequestContext): Promise<void> {
  const url = new URL(request.url ?? "/", "http://gauntlet.invalid")
  try {
    if (url.pathname === "/contact-form-submit") {
      const outcome = url.searchParams.get("outcome") ?? "accepted"
      response.writeHead(303, { location: `/contact-form.html?result=1&outcome=${encodeURIComponent(outcome)}`, "cache-control": "no-store" })
      response.end()
      return
    }
    if (url.pathname === "/stalled-main-world.html") {
      await serveStalledMainWorld(url, response, context)
      return
    }
    if (url.pathname === "/auth/app") {
      if (!hasCookie(request, "bc_auth")) {
        response.writeHead(302, { location: `/auth/sign-in?next=${encodeURIComponent("/auth/app")}`, "cache-control": "no-store" })
        response.end()
        return
      }
      await serveFixture("auth-app.html", response, context)
      return
    }
    if (url.pathname === "/auth/sign-in") {
      await serveFixture("auth-redirect-handoff.html", response, context)
      return
    }
    if (url.pathname === "/auth/reset") {
      response.writeHead(200, {
        "content-type": "text/plain; charset=utf-8",
        "set-cookie": ["bc_auth=; path=/; max-age=0", "bc_csrf=; path=/; max-age=0"],
        "cache-control": "no-store",
      })
      response.end("auth cookies cleared")
      return
    }
    const fileName = url.pathname.replace(/^\/+/, "")
    if (/^[a-z0-9-]+\.html$/.test(fileName)) {
      await serveFixture(fileName, response, context)
      return
    }
    response.writeHead(404, { "content-type": "text/plain; charset=utf-8" })
    response.end("Not found")
  } catch (error) {
    if (!response.headersSent) response.writeHead(500, { "content-type": "text/plain; charset=utf-8" })
    response.end(error instanceof Error ? error.message : "fixture server error")
  }
}

async function serveFixture(fileName: string, response: http.ServerResponse, context: RequestContext): Promise<void> {
  const body = (await readFixture(fileName)).replaceAll(secondaryOriginPlaceholder, context.secondaryOrigin)
  response.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" })
  response.end(body)
}

/**
 * Writes the entire document immediately so it paints, then keeps the response
 * open with periodic HTML comments so document.readyState never leaves
 * "loading". `?hostile=0` serves the same document as a normal, completing page.
 */
async function serveStalledMainWorld(url: URL, response: http.ServerResponse, context: RequestContext): Promise<void> {
  const body = await readFixture("stalled-main-world.html")
  response.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "x-accel-buffering": "no" })
  if (url.searchParams.get("hostile") !== "1") {
    response.end(body)
    return
  }
  response.write(body.replace(/<\/body>\s*<\/html>\s*$/, ""))
  response.flushHeaders()
  context.openStalls.add(response)
  const keepalive = setInterval(() => {
    if (response.destroyed || response.writableEnded) {
      clearInterval(keepalive)
      context.openStalls.delete(response)
      return
    }
    response.write(`<!-- keepalive ${Date.now()} -->\n`)
  }, context.stallKeepaliveMs)
  response.once("close", () => {
    clearInterval(keepalive)
    context.openStalls.delete(response)
  })
}

const fixtureCache = new Map<string, Promise<string>>()

function readFixture(fileName: string): Promise<string> {
  const cached = fixtureCache.get(fileName)
  if (cached) return cached
  const pending = fs.readFile(path.join(fixturesDirectory, fileName), "utf8").catch((error: unknown) => {
    fixtureCache.delete(fileName)
    throw error instanceof Error ? error : new Error(`read fixture ${fileName}`)
  })
  fixtureCache.set(fileName, pending)
  return pending
}

function hasCookie(request: http.IncomingMessage, name: string): boolean {
  const header = request.headers.cookie ?? ""
  return header.split(";").some((part) => part.trim().startsWith(`${name}=`) && part.trim() !== `${name}=`)
}

function listen(server: http.Server, port: number, host: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const onError = (error: NodeJS.ErrnoException) => {
      server.off("listening", onListening)
      reject(error.code === "EADDRINUSE"
        ? new Error(`Gauntlet fixture port ${port} is already in use. Set GAUNTLET_PRIMARY_PORT / GAUNTLET_SECONDARY_PORT to free ports.`, { cause: error })
        : error)
    }
    const onListening = () => {
      server.off("error", onError)
      resolve()
    }
    server.once("error", onError)
    server.once("listening", onListening)
    server.listen(port, host)
  })
}

function closeServer(server: http.Server): Promise<void> {
  return new Promise((resolve) => {
    server.closeAllConnections()
    server.close(() => resolve())
  })
}

import { NodeRuntime, NodeServices } from "@effect/platform-node"
import { ConfigProvider, Console, Effect, Schedule, Schema } from "effect"
import { Command, Flag } from "effect/cli"
import { FetchHttpClient } from "effect/http"
import assert from "node:assert/strict"
import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process"
import { randomUUID } from "node:crypto"
import fs from "node:fs/promises"
import net from "node:net"
import os from "node:os"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { WebSocket } from "ws"
import { parseExtensionCommand } from "../src/protocol.ts"
import * as RelayClient from "../src/relay-client.ts"
import { RelayLifecycleEvent } from "../src/relay-lifecycle-log.ts"
import { ExtensionStatus, RelayVersion, SessionsContainer } from "../src/relay-schema.ts"
import { defaultSessionCatalogPath, SessionCatalog } from "../src/session-catalog.ts"

const attempt = <A>(run: () => Promise<A>) => Effect.tryPromise({
  try: run, catch: (cause) => cause instanceof Error ? cause : new Error(String(cause)),
})
const wait = <A, E, R>(effect: Effect.Effect<A, E, R>) => effect.pipe(
  Effect.retry({ times: 160, schedule: Schedule.spaced("50 millis") }), Effect.timeout("15 seconds"),
)
const decode = <S extends Schema.ConstraintDecoder<unknown>>(schema: S, text: string) =>
  Schema.decodeUnknownSync(Schema.fromJsonString(schema))(text)
const identity = RelayVersion.pipe(Schema.fieldsAssign({
  instanceId: Schema.String, buildId: Schema.String, pid: Schema.Number,
  managed: Schema.Literal(true), shutdownProtocol: Schema.Literal(2),
}))
const fixtureSession = "lifecycle-adopted"
const targetInfo = { targetId: "lifecycle-target", type: "page", title: "Synthetic lifecycle fixture", url: "https://lifecycle.invalid/", attached: true, canAccessOpener: false }
const origin = "chrome-extension://aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
type Child = { child: ChildProcessWithoutNullStreams; closed: Promise<number | null>; managed: boolean; output: () => { stdout: string; stderr: string } }

const artifact = Effect.fn("LifecycleCheck.artifact")(function* (prefix: string) {
  return yield* attempt(async () => {
    assert(path.isAbsolute(prefix), "Use an absolute standalone install prefix")
    assert(!(await fs.lstat(prefix)).isSymbolicLink(), "Use the install directory, not an active-install symlink")
    const directory = await fs.realpath(prefix)
    const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)))
    assert(directory !== root && !directory.startsWith(`${root}${path.sep}`), "Install must be outside the checkout")
    const marker = decode(Schema.Struct({ format: Schema.Literal(1), version: Schema.String, digest: Schema.String }), await fs.readFile(path.join(directory, ".browser-control-runtime.json"), "utf8"))
    const pkg = path.join(directory, "node_modules/@opencode-ai/browser-control")
    const manifest = decode(Schema.Struct({ name: Schema.Literal("@opencode-ai/browser-control"), version: Schema.String }), await fs.readFile(path.join(pkg, "package.json"), "utf8"))
    assert.equal(manifest.version, marker.version)
    for (const entry of ["cli.js", "mcp.js"]) assert.equal(await fs.realpath(path.join(pkg, "dist", entry)), path.join(pkg, "dist", entry))
    return { cli: path.join(pkg, "dist/cli.js"), mcp: path.join(pkg, "dist/mcp.js"), version: manifest.version }
  })
})

// Binding also proves absence during cleanup; never discover or signal a port's PID.
const bindAndRelease = (port: number) => attempt(() => new Promise<number>((resolve, reject) => {
  const server = net.createServer()
  server.once("error", reject)
  server.listen(port, "127.0.0.1", () => {
    const address = server.address()
    server.close((error) => {
      if (error) reject(error)
      else if (!address || typeof address === "string") reject(new Error("Missing fixture TCP address"))
      else resolve(address.port)
    })
  })
}))

const check = Effect.fn("LifecycleCheck.run")(function* (options: { previous: string; candidate: string }) {
  assert(!process.versions.bun, "Run this script with Node/tsx so installed artifacts use absolute-path Node")
  const [previous, candidate] = yield* Effect.all([artifact(options.previous), artifact(options.candidate)])
  assert.notEqual(previous.cli, candidate.cli, "Prepare two independent installs")
  const port = yield* bindAndRelease(0)
  assert.notEqual(port, 19989, "Never use the production relay port")
  const scratch = path.join(os.tmpdir(), "opencode")
  yield* attempt(() => fs.mkdir(scratch, { recursive: true }))
  const home = yield* attempt(() => fs.mkdtemp(path.join(scratch, "bc-lifecycle-")))
  const env = {
    HOME: home, USERPROFILE: home, PATH: path.join(home, "bin"), TMPDIR: path.join(home, "tmp"),
    XDG_CONFIG_HOME: path.join(home, "config"), XDG_STATE_HOME: path.join(home, "state"), XDG_CACHE_HOME: path.join(home, "cache"),
    BROWSER_CONTROL_PORT: String(port), BROWSER_CONTROL_EXTENSION_ORIGINS: origin, NO_COLOR: "1",
  }
  const relay = yield* RelayClient.make({ endpoint: RelayClient.endpointForPort(port) }).pipe(
    Effect.provide(FetchHttpClient.layer), Effect.provide(ConfigProvider.layer(ConfigProvider.fromUnknown(env))),
  )
  const catalog = new SessionCatalog(defaultSessionCatalogPath(port, home))
  const log = path.join(path.dirname(catalog.filePath), "lifecycle.jsonl")
  const events = () => attempt(async () => {
    assert((await fs.stat(log)).size <= 256_000, "Fixture lifecycle log exceeded its bound")
    const text = await fs.readFile(log, "utf8")
    return text.trim().split("\n").map((line) => decode(RelayLifecycleEvent, line))
  })
  const children: Child[] = []
  const sockets: WebSocket[] = []
  const forbidden: string[] = []
  let adapterError: Error | undefined
  function launch(entry: string, args: string[], managed = false): Child {
    const child = spawn(process.execPath, [entry, ...args], { cwd: home, env: { ...env, ...(managed ? { BROWSER_CONTROL_MANAGED_RELAY: "1" } : {}) }, stdio: "pipe" })
    let stdout = "", stderr = ""
    child.stdout.on("data", (data) => { stdout = (stdout + String(data)).slice(-32_768) })
    child.stderr.on("data", (data) => { stderr = (stderr + String(data)).slice(-32_768) })
    child.on("error", (error) => { stderr = (stderr + error.message).slice(-32_768) })
    child.stdin.on("error", () => {})
    const closed = new Promise<number | null>((resolve) => child.once("close", resolve))
    const result = { child, closed, managed, output: () => ({ stdout, stderr }) }
    children.push(result)
    return result
  }
  const run = Effect.fn("LifecycleCheck.command")(function* (entry: string, args: string[]) {
    const process = launch(entry, args)
    const code = yield* attempt(() => process.closed).pipe(Effect.timeout("20 seconds"))
    return { code, ...process.output() }
  })
  // A failed cleanup retains HOME. Only fixture-recorded identities receive shutdown.
  yield* Effect.addFinalizer(() => Effect.gen(function* () {
    for (const process of children.filter((item) => !item.managed)) {
      if (process.child.exitCode === null && process.child.signalCode === null) process.child.kill("SIGTERM")
      yield* attempt(() => process.closed).pipe(Effect.timeout("5 seconds"))
    }
    const current = yield* Effect.result(relay.version.pipe(Effect.timeout("3 seconds")))
    if (current._tag === "Success") {
      const owned = yield* Schema.decodeUnknownEffect(identity)(current.success)
      assert((yield* events()).some((event) => event._tag === "Ready" && event.instanceId === owned.instanceId), "Refusing to shut down an unowned listener")
      yield* relay.shutdown({ instanceId: owned.instanceId, requestId: randomUUID(), reason: "explicit-restart", client: { kind: "sdk", instanceId: randomUUID(), buildId: owned.buildId } }).pipe(Effect.timeout("15 seconds"))
    } else if (!(current.failure instanceof RelayClient.RelayUnreachable)) {
      return yield* Effect.fail(new Error("Cannot identify fixture relay for safe cleanup"))
    }
    for (const process of children.filter((item) => item.managed)) {
      // A directly spawned serve may have failed before publishing its identity.
      if (current._tag === "Failure" && process.child.exitCode === null && process.child.signalCode === null) process.child.kill("SIGTERM")
      yield* attempt(() => process.closed).pipe(Effect.timeout("5 seconds"))
    }
    yield* wait(bindAndRelease(port))
    assert.deepEqual(forbidden, [], "Lifecycle sent destructive extension commands")
    if (adapterError) throw adapterError
    yield* attempt(() => fs.rm(home, { recursive: true }))
  }).pipe(
    Effect.tapCause(() => Console.error(`Cleanup failed; fixture retained at ${home}`)), Effect.orDie,
    Effect.ensuring(Effect.sync(() => { for (const socket of sockets) socket.terminate() })),
  ))

  const connectExtension = Effect.fn("LifecycleCheck.extension")(function* () {
    const socket = new WebSocket(`ws://127.0.0.1:${port}/extension`, { origin })
    sockets.push(socket)
    socket.on("error", (error) => { adapterError = error })
    socket.on("message", (data) => {
      try {
        const command = parseExtensionCommand(data.toString())
        if (["tabs.remove", "debugger.detach", "tabs.create", "runtime.reload"].includes(command.method)) forbidden.push(command.method)
        const result = command.method === "debugger.sendCommand" && command.params?.method === "Target.getTargetInfo" ? { targetInfo } : {}
        socket.send(JSON.stringify({ id: command.id, result }))
      } catch (cause) { adapterError = cause instanceof Error ? cause : new Error(String(cause)) }
    })
    yield* attempt(() => new Promise<void>((resolve, reject) => { socket.once("open", resolve); socket.once("error", reject) })).pipe(Effect.timeout("5 seconds"))
    socket.send(JSON.stringify({ method: "hello", params: { version: "lifecycle-fixture", protocolVersion: 2 } }))
    socket.send(JSON.stringify({ method: "debugger.attached", params: { tabId: 1 } }))
    socket.send(JSON.stringify({ method: "ready" }))
    yield* wait(relay.extensionStatus.pipe(Effect.flatMap((status) => Effect.try(() => {
      assert(status.connected && status.protocolCompatible === true && status.protocolVersion === 2)
      assert.equal(status.targets?.length, 1)
      const target = status.targets[0]
      assert(target && target.id === targetInfo.targetId && target.tabId === 1 && target.owner === "user" && target.browserControlSessionId === fixtureSession)
    }))))
    return socket
  })
  const mcpStatus = Effect.fn("LifecycleCheck.mcp")(function* () {
    const process = launch(candidate.mcp, [])
    const result = yield* attempt(() => new Promise<unknown>((resolve, reject) => {
      let buffer = ""
      const send = (message: unknown) => process.child.stdin.write(`${JSON.stringify(message)}\n`)
      process.closed.then(() => reject(new Error("MCP exited before status response")))
      process.child.stdout.on("data", (data) => {
        buffer += String(data)
        try {
          assert(buffer.length <= 65_536, "MCP output exceeded fixture bound")
          while (buffer.includes("\n")) {
            const end = buffer.indexOf("\n"), line = buffer.slice(0, end)
            buffer = buffer.slice(end + 1)
            const response = decode(Schema.Struct({ jsonrpc: Schema.Literal("2.0"), id: Schema.optionalKey(Schema.Number), result: Schema.optionalKey(Schema.Unknown), error: Schema.optionalKey(Schema.Unknown) }), line)
            assert.equal(response.error, undefined, "MCP returned a protocol error")
            if (response.id === 1) {
              Schema.decodeUnknownSync(Schema.Struct({ protocolVersion: Schema.Literal("2025-06-18"), serverInfo: Schema.Struct({ name: Schema.Literal("browser-control"), version: Schema.Literal(candidate.version) }), capabilities: Schema.Struct({ tools: Schema.Unknown }) }))(response.result)
              send({ jsonrpc: "2.0", method: "notifications/initialized" })
              send({ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} })
            } else if (response.id === 2) {
              const tools = Schema.decodeUnknownSync(Schema.Struct({ tools: Schema.Array(Schema.Struct({ name: Schema.String })) }))(response.result)
              assert(tools.tools.some((tool) => tool.name === "status"))
              send({ jsonrpc: "2.0", id: 3, method: "tools/call", params: { name: "status", arguments: {} } })
            } else if (response.id === 3) resolve(response.result)
          }
        } catch (error) { reject(error) }
      })
      send({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "lifecycle-fixture", version: "1" } } })
    })).pipe(Effect.timeout("15 seconds"))
    const decoded = yield* Schema.decodeUnknownEffect(Schema.Struct({ isError: Schema.optionalKey(Schema.Literal(false)), structuredContent: Schema.Struct({ version: identity, status: ExtensionStatus, buildProblem: Schema.String }) }))(result)
    process.child.kill("SIGTERM")
    yield* attempt(() => process.closed).pipe(Effect.timeout("5 seconds"))
    return decoded.structuredContent
  })

  return yield* Effect.gen(function* () {
    yield* attempt(async () => { for (const directory of [env.PATH, env.TMPDIR, env.XDG_CONFIG_HOME, env.XDG_STATE_HOME, env.XDG_CACHE_HOME]) await fs.mkdir(directory) })
    const timestamp = new Date().toISOString()
    // Synthetic catalog restoration only: no Playwright connection or real browser adoption.
    yield* attempt(() => catalog.save([{ id: fixtureSession, createdAt: timestamp, updatedAt: timestamp, readOnly: true, target: { id: targetInfo.targetId, owner: "user" } }]))
    const serve = launch(previous.cli, ["serve"], true)
    const before = yield* wait(relay.version.pipe(Effect.flatMap(Schema.decodeUnknownEffect(identity))))
    assert.equal(before.pid, serve.child.pid, "Fixture port was claimed by another process")
    assert.equal(before.version, previous.version)
    const oldSocket = yield* connectExtension()
    const oldClosed = new Promise<void>((resolve) => oldSocket.once("close", () => resolve()))
    const ordinary = yield* run(candidate.cli, ["session", "list", "--json"])
    assert.notEqual(ordinary.code, 0, "Different-build ordinary CLI must refuse work")
    assert.match(ordinary.stdout + ordinary.stderr, /does not match CLI build/)
    assert.equal((yield* relay.version).instanceId, before.instanceId)
    const status = yield* mcpStatus()
    assert.equal(status.version.instanceId, before.instanceId)
    assert(status.status.connected)
    assert.equal((yield* relay.version).instanceId, before.instanceId)
    assert.equal((yield* events()).filter((event) => event._tag === "Requested").length, 0)

    const restarted = yield* run(candidate.cli, ["relay", "restart"])
    assert.equal(restarted.code, 0, restarted.stderr.slice(-4_096))
    yield* attempt(() => oldClosed).pipe(Effect.timeout("5 seconds"))
    yield* attempt(() => serve.closed).pipe(Effect.timeout("5 seconds"))
    const after = yield* wait(relay.version.pipe(Effect.flatMap(Schema.decodeUnknownEffect(identity))))
    assert.notEqual(after.instanceId, before.instanceId)
    assert.equal(after.version, candidate.version)
    assert(Date.parse(after.buildId) > Date.parse(before.buildId), "Candidate must be a strictly later ordered build")
    const audit = yield* events()
    const request = audit.find((event) => event._tag === "Requested")
    assert(request?._tag === "Requested" && request.instanceId === before.instanceId && request.client.kind === "cli" && request.client.buildId === after.buildId)
    assert(audit.some((event) => event._tag === "Stopping" && event.instanceId === before.instanceId && event.requestId === request.requestId))
    assert(audit.some((event) => event._tag === "Ready" && event.instanceId === after.instanceId && event.restartRequestId === request.requestId))
    yield* connectExtension()
    const listed = yield* run(candidate.cli, ["session", "list", "--json"])
    assert.equal(listed.code, 0, listed.stderr.slice(-4_096))
    const sessions = decode(SessionsContainer, listed.stdout).sessions
    assert.equal(sessions.length, 1)
    assert(sessions[0]?.id === fixtureSession && sessions[0].readOnly === true)
    assert.deepEqual((yield* attempt(() => catalog.load()))[0]?.target, { id: targetInfo.targetId, owner: "user" })
    const downgrade = yield* run(previous.cli, ["relay", "restart"])
    assert.notEqual(downgrade.code, 0)
    assert.match(downgrade.stdout + downgrade.stderr, /Refusing to downgrade/)
    assert.equal((yield* relay.version).instanceId, after.instanceId)
    assert.equal((yield* events()).filter((event) => event._tag === "Requested").length, 1)
    return `PASS: installed-artifact lifecycle mechanism test (${before.buildId} -> ${after.buildId}). Synthetic adopted-target restoration only; not cross-release compatibility or real browser adoption proof.`
  }).pipe(Effect.tapCause(() => Console.error(`Fixture diagnostics (${home}):\n${children.map((child) => child.output().stderr.slice(-2_048)).join("\n").slice(-8_192)}`)))
})

Command.make("check-runtime-lifecycle", {
  previous: Flag.String("previous").pipe(Flag.withDescription("Absolute standalone install prefix; requires shutdown protocol 2")),
  candidate: Flag.String("candidate").pipe(Flag.withDescription("Absolute standalone install prefix with a strictly later build id")),
}, (options) => check(options).pipe(Effect.scoped, Effect.flatMap(Console.log))).pipe(
  Command.run({ version: "1" }), Effect.provide(NodeServices.layer), NodeRuntime.runMain,
)

import { Effect, Schema, Semaphore } from "effect"
import { spawn } from "node:child_process"
import fs from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { terminateChildProcess } from "./child-process.ts"
import { isNodeError, writeJsonFileAtomically } from "./fs-durability.ts"
import { redactKnownValues, type CredentialSlot } from "./network-redaction.ts"

const StoredCredentialSlot = Schema.Struct({
  ref: Schema.String.check(Schema.isPattern(/^BC_SECRET_[1-9][0-9]*$/)),
  value: Schema.String,
  sources: Schema.Array(Schema.String),
  expiresAt: Schema.optionalKey(Schema.String),
})

const StoredAuthProfile = Schema.Struct({
  version: Schema.Literal(1),
  name: Schema.String,
  createdAt: Schema.String,
  updatedAt: Schema.String,
  slots: Schema.Array(StoredCredentialSlot),
}).check(Schema.makeFilter((profile) => {
  const refs = profile.slots.map((slot) => slot.ref)
  if (new Set(refs).size !== refs.length) return "Auth profile refs must be unique"
  const sources = profile.slots.flatMap((slot) => slot.sources)
  return new Set(sources).size === sources.length ? undefined : "Auth profile sources must be unique"
}))

interface AuthProfile extends Schema.Schema.Type<typeof StoredAuthProfile> {}

export type AuthProfileSummary = {
  readonly name: string
  readonly createdAt: string
  readonly updatedAt: string
  readonly slotCount: number
  readonly slots: readonly {
    readonly ref: string
    readonly sources: readonly string[]
    readonly expiresAt?: string
    readonly expired: boolean
  }[]
}

export type AuthRunResult = {
  readonly exitCode: number
  readonly signal: NodeJS.Signals | null
  readonly stdout: string
  readonly stderr: string
  readonly stdoutTruncated: boolean
  readonly stderrTruncated: boolean
  readonly durationMs: number
}

export interface AuthProfileOptions {
  readonly baseDir?: string
}

export interface AuthRunOptions extends AuthProfileOptions {
  readonly name: string
  readonly command: string
  readonly args?: readonly string[]
  readonly cwd?: string
  readonly timeoutMs?: number
  readonly maxOutputBytes?: number
}

export class AuthProfileError extends Schema.TaggedError<AuthProfileError>()(
  "AuthProfile.Error",
  {
    message: Schema.String,
    operation: Schema.String,
    reason: Schema.Literals(["invalid-name", "not-found", "read-failed", "invalid-json", "invalid-profile", "write-failed", "run-failed"]),
    cause: Schema.optionalKey(Schema.Defect()),
  },
) {}

const defaultBaseDir = (): string => path.join(os.homedir(), ".browser-control", "secrets")
const writeLock = Semaphore.makeUnsafe(1)
const profileLockTimeoutMs = 30_000
const staleProfileLockMs = 60_000
const maximumRunOutputBytes = 10_000_000
const maximumTimeoutMs = 2_147_483_647

export const read = Effect.fn("AuthProfile.read")(function* (name: string, options: { readonly baseDir?: string } = {}) {
  const filePath = yield* profilePath(options.baseDir ?? defaultBaseDir(), name)
  const text = yield* Effect.tryPromise({
    try: () => fs.readFile(filePath, "utf8"),
    catch: (cause) => isNodeError(cause) && cause.code === "ENOENT"
      ? new AuthProfileError({ message: `Auth profile not found: ${name}`, operation: "read", reason: "not-found", cause })
      : new AuthProfileError({ message: `Could not read auth profile: ${name}`, operation: "read", reason: "read-failed", cause }),
  })
  return yield* Schema.decodeUnknownEffect(StoredAuthProfile)(yield* Effect.try({
    try: () => JSON.parse(text),
    catch: (cause) => new AuthProfileError({ message: `Auth profile is not valid JSON: ${name}`, operation: "read", reason: "invalid-json", cause }),
  })).pipe(
    Effect.mapError((cause) => cause instanceof AuthProfileError
      ? cause
      : new AuthProfileError({ message: `Auth profile has an invalid shape: ${name}`, operation: "read", reason: "invalid-profile", cause })),
  )
})

export const readOptional = Effect.fn("AuthProfile.readOptional")(function* (name: string, options: { readonly baseDir?: string } = {}) {
  return yield* read(name, options).pipe(
    Effect.catchIf((error) => error.reason === "not-found", () => Effect.succeed(undefined)),
  )
})

export function withLock<A, E, R>(
  name: string,
  options: { readonly baseDir?: string },
  effect: Effect.Effect<A, E, R>,
): Effect.Effect<A, E | AuthProfileError, R> {
  const baseDir = options.baseDir ?? defaultBaseDir()
  const acquire = Effect.gen(function* () {
    const filePath = yield* profilePath(baseDir, name)
    const lockPath = `${filePath}.lock`
    yield* Effect.tryPromise({
      try: async () => {
        await fs.mkdir(baseDir, { recursive: true, mode: 0o700 })
        await fs.chmod(baseDir, 0o700)
        const deadline = Date.now() + profileLockTimeoutMs
        while (true) {
          try {
            const handle = await fs.open(lockPath, "wx", 0o600)
            let written = false
            try {
              await handle.writeFile(`${process.pid}\n`)
              written = true
            } finally {
              await handle.close()
              if (!written) await fs.unlink(lockPath).catch(() => {})
            }
            return
          } catch (cause) {
            if (!isNodeError(cause) || cause.code !== "EEXIST") throw cause
            const stat = await fs.stat(lockPath).catch(() => undefined)
            if (stat && Date.now() - stat.mtimeMs > staleProfileLockMs) {
              await fs.unlink(lockPath).catch(() => {})
              continue
            }
            if (Date.now() >= deadline) throw new Error(`Timed out waiting for auth profile lock: ${name}`)
            await new Promise((resolve) => setTimeout(resolve, 25))
          }
        }
      },
      catch: (cause) => new AuthProfileError({ message: `Could not lock auth profile: ${name}`, operation: "lock", reason: "write-failed", cause }),
    })
    return lockPath
  })
  return Effect.acquireUseRelease(
    acquire,
    () => effect,
    (lockPath) => Effect.tryPromise({
      try: () => fs.unlink(lockPath).catch(() => {}).then(() => {}),
      catch: (cause) => new AuthProfileError({ message: `Could not release auth profile lock: ${name}`, operation: "lock", reason: "write-failed", cause }),
    }),
  )
}

const writeProfile = Effect.fnUntraced(function* (options: {
  readonly name: string
  readonly slots: readonly CredentialSlot[]
  readonly baseDir?: string
}) {
  const baseDir = options.baseDir ?? defaultBaseDir()
  const filePath = yield* profilePath(baseDir, options.name)
  const existing = yield* readOptional(options.name, { baseDir })
  const now = new Date().toISOString()
  const profile: AuthProfile = {
    version: 1,
    name: options.name,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
    slots: options.slots.map((slot) => ({
      ref: slot.ref,
      value: slot.value,
      sources: [...slot.sources],
      ...(slot.expiresAt ? { expiresAt: slot.expiresAt } : {}),
    })),
  }
  yield* Schema.decodeUnknownEffect(StoredAuthProfile)(profile).pipe(
    Effect.mapError((cause) => new AuthProfileError({ message: `Auth profile has an invalid shape: ${options.name}`, operation: "write", reason: "invalid-profile", cause })),
  )
  if (existing && sameSlots(existing.slots, profile.slots)) return summary(existing)
  yield* Effect.tryPromise({
    try: () => writeJsonFileAtomically(filePath, profile, { dirMode: 0o700 }),
    catch: (cause) => new AuthProfileError({ message: `Could not write auth profile: ${options.name}`, operation: "write", reason: "write-failed", cause }),
  })
  return summary(profile)
})

export const write = Effect.fn("AuthProfile.write")(function* (options: {
  readonly name: string
  readonly slots: readonly CredentialSlot[]
  readonly baseDir?: string
}) {
  return yield* writeLock.withPermit(writeProfile(options))
})

export const status = Effect.fn("AuthProfile.status")(function* (name: string, options: AuthProfileOptions = {}) {
  return summary(yield* read(name, options))
})

export const run = Effect.fn("AuthProfile.run")(function* (options: AuthRunOptions) {
  if (!options.command.trim()) {
    return yield* new AuthProfileError({ message: "Auth command must not be empty", operation: "run", reason: "run-failed" })
  }
  const timeoutMs = options.timeoutMs ?? 120_000
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs <= 0 || timeoutMs > maximumTimeoutMs) {
    return yield* new AuthProfileError({ message: `Auth command timeout must be an integer between 1 and ${maximumTimeoutMs} milliseconds`, operation: "run", reason: "run-failed" })
  }
  const maxOutputBytes = options.maxOutputBytes ?? 1_000_000
  if (!Number.isSafeInteger(maxOutputBytes) || maxOutputBytes < 0 || maxOutputBytes > maximumRunOutputBytes) {
    return yield* new AuthProfileError({ message: `Auth command output limit must be an integer between 0 and ${maximumRunOutputBytes} bytes`, operation: "run", reason: "run-failed" })
  }
  const profile = yield* read(options.name, { ...(options.baseDir ? { baseDir: options.baseDir } : {}) })
  const startedAt = Date.now()
  const maxSecretBytes = <REDACTED> slot) => Math.max(max, Buffer.byteLength(slot.value)), 0)
  const result = yield* runChild({
      command: options.command,
      args: options.args ?? [],
      ...(options.cwd ? { cwd: options.cwd } : {}),
      timeoutMs,
      maxOutputBytes: maxOutputBytes + maxSecretBytes,
      env: Object.fromEntries(profile.slots.map((slot) => [slot.ref, slot.value])),
    }).pipe(
      Effect.mapError((cause) => new AuthProfileError({ message: `Could not run command with auth profile ${options.name}`, operation: "run", reason: "run-failed", cause })),
    )
  const stdout = redactOutput(result.stdout, profile.slots, maxOutputBytes)
  const stderr = redactOutput(result.stderr, profile.slots, maxOutputBytes)
  return {
    ...result,
    stdout: stdout.text,
    stderr: stderr.text,
    stdoutTruncated: result.stdoutTruncated || stdout.truncated,
    stderrTruncated: result.stderrTruncated || stderr.truncated,
    durationMs: Date.now() - startedAt,
  } satisfies AuthRunResult
})

function summary(profile: AuthProfile): AuthProfileSummary {
  const now = Date.now()
  return {
    name: profile.name,
    createdAt: profile.createdAt,
    updatedAt: profile.updatedAt,
    slotCount: profile.slots.length,
    slots: profile.slots.map((slot) => ({
      ref: slot.ref,
      sources: [...slot.sources],
      ...(slot.expiresAt ? { expiresAt: slot.expiresAt } : {}),
      expired: slot.expiresAt ? Date.parse(slot.expiresAt) <= now : false,
    })),
  }
}

function profilePath(baseDir: string, name: string): Effect.Effect<string, AuthProfileError> {
  return /^[a-z0-9][a-z0-9._-]{0,63}$/i.test(name)
    ? Effect.succeed(path.join(baseDir, `${name}.json`))
    : Effect.fail(new AuthProfileError({ message: `Invalid auth profile name: ${name}`, operation: "path", reason: "invalid-name" }))
}

function sameSlots(left: readonly CredentialSlot[], right: readonly CredentialSlot[]): boolean {
  return JSON.stringify(left) === JSON.stringify(right)
}

function redactOutput(text: string, slots: readonly CredentialSlot[], maxBytes: number): { readonly text: string; readonly truncated: boolean } {
  const bytes = Buffer.from(text)
  let cutoff = Math.min(bytes.length, maxBytes)
  let changed = true
  while (changed) {
    changed = false
    for (const slot of slots) {
      if (!slot.value) continue
      const secret = <REDACTED>
      let start = bytes.indexOf(secret)
      while (start >= 0 && start < cutoff) {
        if (start + secret.length > cutoff) {
          cutoff = start
          changed = true
          break
        }
        start = bytes.indexOf(secret, start + secret.length)
      }
    }
  }
  return {
    text: redactKnownValues(bytes.subarray(0, cutoff).toString("utf8"), slots),
    truncated: cutoff < bytes.length,
  }
}

function runChild(options: {
  readonly command: string
  readonly args: readonly string[]
  readonly cwd?: string
  readonly timeoutMs: number
  readonly maxOutputBytes: number
  readonly env: Readonly<Record<string, string>>
}): Effect.Effect<Omit<AuthRunResult, "durationMs">, Error> {
  return Effect.callback((resume) => {
    const child = spawn(options.command, [...options.args], {
      ...(options.cwd ? { cwd: options.cwd } : {}),
      env: childEnvironment(options.env),
      detached: process.platform !== "win32",
      stdio: ["ignore", "pipe", "pipe"],
    })
    const stdout: Buffer[] = []
    const stderr: Buffer[] = []
    let stdoutBytes = 0
    let stderrBytes = 0
    let stdoutTruncated = false
    let stderrTruncated = false
    const append = (chunks: Buffer[], chunk: Buffer, currentBytes: number): number => {
      const remaining = options.maxOutputBytes - currentBytes
      if (remaining <= 0) return currentBytes
      chunks.push(chunk.subarray(0, remaining))
      return currentBytes + Math.min(chunk.length, remaining)
    }
    child.stdout.on("data", (chunk: Buffer) => {
      const next = append(stdout, chunk, stdoutBytes)
      stdoutTruncated ||= next - stdoutBytes < chunk.length
      stdoutBytes = next
    })
    child.stderr.on("data", (chunk: Buffer) => {
      const next = append(stderr, chunk, stderrBytes)
      stderrTruncated ||= next - stderrBytes < chunk.length
      stderrBytes = next
    })
    let closed = false
    let settled = false
    let closePromiseResolve: (() => void) | undefined
    const closePromise = new Promise<void>((resolve) => {
      closePromiseResolve = resolve
    })
    const timeout = setTimeout(() => {
      void terminateChildProcess({ child, exit: closePromise, graceMs: 1_000, isExited: () => closed })
    }, options.timeoutMs)
    child.once("error", (cause) => {
      clearTimeout(timeout)
      closed = true
      closePromiseResolve?.()
      if (settled) return
      settled = true
      resume(Effect.fail(cause))
    })
    child.once("close", (code, signal) => {
      clearTimeout(timeout)
      closed = true
      closePromiseResolve?.()
      if (settled) return
      settled = true
      resume(Effect.succeed({
        exitCode: code ?? 1,
        signal,
        stdout: Buffer.concat(stdout).toString("utf8"),
        stderr: Buffer.concat(stderr).toString("utf8"),
        stdoutTruncated,
        stderrTruncated,
      }))
    })
    return Effect.promise(() => terminateChildProcess({ child, exit: closePromise, graceMs: 1_000, isExited: () => closed }))
  })
}

function childEnvironment(profile: Readonly<Record<string, string>>): NodeJS.ProcessEnv {
  const inherited = Object.fromEntries(
    Object.entries(process.env).filter(([name]) => !/^BC_SECRET_[1-9][0-9]*$/.test(name)),
  )
  return { ...inherited, ...profile }
}

import { Effect, Match, Schema } from "effect"
import type { Page } from "playwright-core"
import {
  AuthenticatedJsonOutcome,
  type AuthenticatedJsonMethod,
  type AuthenticatedJsonRequest,
} from "./relay-schema.ts"

const defaultTimeoutMs = 30_000
const defaultMaxResponseBytes = 2_000_000

export class AuthenticatedOriginError extends Schema.TaggedError<AuthenticatedOriginError>()(
  "AuthenticatedOrigin.Error",
  {
    message: Schema.String,
    reason: Schema.Literals(["invalid-request", "page-failed"]),
    cause: Schema.optionalKey(Schema.Defect()),
  },
) {}

type RequestOptions = Omit<AuthenticatedJsonRequest, "sessionId">

type PageRequestInput = {
  readonly origin: string
  readonly method: AuthenticatedJsonMethod
  readonly url: string
  readonly headers?: Readonly<Record<string, string>>
  readonly body?: unknown
  readonly timeoutMs: number
  readonly maxResponseBytes: number
}

export const requestJson = Effect.fn("AuthenticatedOrigin.requestJson")(function* (
  page: Page,
  request: RequestOptions,
) {
  const target = yield* Effect.try({
    try: () => {
      const origin = normalizeOrigin(request.origin)
      return {
        origin,
        requestUrl: resolveRequestUrl(origin, request.path),
        startUrl: request.startUrl === undefined ? undefined : resolveStartUrl(origin, request.startUrl),
      }
    },
    catch: (cause) => cause instanceof AuthenticatedOriginError
      ? cause
      : new AuthenticatedOriginError({
          message: "Invalid authenticated origin request",
          reason: "invalid-request",
          cause,
        }),
  })
  const { origin, requestUrl, startUrl } = target

  if (pageOrigin(page.url()) !== origin && startUrl !== undefined) {
    yield* Effect.tryPromise({
      try: () => page.goto(startUrl, { waitUntil: "domcontentloaded", timeout: request.timeoutMs ?? defaultTimeoutMs }),
      catch: (cause) => new AuthenticatedOriginError({
        message: cause instanceof Error ? cause.message : "Navigate to authenticated origin",
        reason: "page-failed",
        cause,
      }),
    })
  }

  const actualOrigin = pageOrigin(page.url())
  if (actualOrigin !== origin) {
    return AuthenticatedJsonOutcome.cases.OriginMismatch.make({
      expectedOrigin: origin,
      actualOrigin,
    })
  }

  const input: PageRequestInput = {
    origin,
    method: request.method,
    url: requestUrl,
    ...(request.headers === undefined ? {} : { headers: request.headers }),
    ...(request.body === undefined ? {} : { body: request.body }),
    timeoutMs: request.timeoutMs ?? defaultTimeoutMs,
    maxResponseBytes: request.maxResponseBytes ?? defaultMaxResponseBytes,
  }

  const pageResult = yield* Effect.tryPromise({
    try: () => page.evaluate(runPageRequest, input),
    catch: (cause) => new AuthenticatedOriginError({
      message: cause instanceof Error ? cause.message : "Run authenticated page request",
      reason: "page-failed",
      cause,
    }),
  }).pipe(Effect.uninterruptible)

  return Match.value(pageResult).pipe(
    Match.when({ kind: "OriginMismatch" }, ({ expectedOrigin, actualOrigin }) =>
      AuthenticatedJsonOutcome.cases.OriginMismatch.make({ expectedOrigin, actualOrigin })),
    Match.when({ kind: "HttpError" }, ({ status }) =>
      AuthenticatedJsonOutcome.cases.HttpError.make({ status })),
    Match.when({ kind: "ResponseTooLarge" }, ({ status, maxResponseBytes }) =>
      AuthenticatedJsonOutcome.cases.ResponseTooLarge.make({ status, maxResponseBytes })),
    Match.when({ kind: "Success" }, ({ status, value }) =>
      AuthenticatedJsonOutcome.cases.Success.make({ status, value })),
    Match.when({ kind: "InvalidJson" }, ({ status }) =>
      AuthenticatedJsonOutcome.cases.InvalidJson.make({ status })),
    Match.when({ kind: "RequestFailed" }, ({ outcome }) =>
      AuthenticatedJsonOutcome.cases.RequestFailed.make({ outcome })),
    Match.exhaustive,
  )
})

export function normalizeOrigin(value: string): string {
  let url: URL
  try {
    url = new URL(value)
  } catch (cause) {
    throw new AuthenticatedOriginError({
      message: `Invalid authenticated origin: ${value}`,
      reason: "invalid-request",
      cause,
    })
  }
  if ((url.protocol !== "https:" && url.protocol !== "http:") || url.username || url.password) {
    throw new AuthenticatedOriginError({
      message: `Authenticated origin must be an HTTP(S) origin without credentials: ${value}`,
      reason: "invalid-request",
    })
  }
  if (url.pathname !== "/" || url.search || url.hash) {
    throw new AuthenticatedOriginError({
      message: `Authenticated origin must not include a path, query, or fragment: ${value}`,
      reason: "invalid-request",
    })
  }
  return url.origin
}

function resolveRequestUrl(origin: string, path: string): string {
  if (!path.startsWith("/") || path.startsWith("//")) {
    throw new AuthenticatedOriginError({
      message: "Authenticated request path must start with one slash",
      reason: "invalid-request",
    })
  }
  const url = new URL(path, origin)
  if (url.origin !== origin) {
    throw new AuthenticatedOriginError({
      message: `Authenticated request escaped its declared origin: ${path}`,
      reason: "invalid-request",
    })
  }
  return url.toString()
}

export function resolveStartUrl(origin: string, value: string): string {
  const url = new URL(value, origin)
  if (url.origin !== origin) {
    throw new AuthenticatedOriginError({
      message: `Authenticated origin startUrl must stay on ${origin}`,
      reason: "invalid-request",
    })
  }
  return url.toString()
}

function pageOrigin(value: string): string {
  try {
    return new URL(value).origin
  } catch {
    return "null"
  }
}

type PageRequestResult =
  | { readonly kind: "OriginMismatch"; readonly expectedOrigin: string; readonly actualOrigin: string }
  | { readonly kind: "HttpError"; readonly status: number }
  | { readonly kind: "ResponseTooLarge"; readonly status: number; readonly maxResponseBytes: number }
  | { readonly kind: "Success"; readonly status: number; readonly value: Schema.Schema.Type<typeof Schema.Json> }
  | { readonly kind: "InvalidJson"; readonly status: number }
  | { readonly kind: "RequestFailed"; readonly outcome: "not-sent" | "unknown" }

async function runPageRequest(input: PageRequestInput): Promise<PageRequestResult> {
  if (window.location.origin !== input.origin) {
    return {
      kind: "OriginMismatch",
      expectedOrigin: input.origin,
      actualOrigin: window.location.origin,
    }
  }

  const controller = new AbortController()
  const timeout = window.setTimeout(() => controller.abort(), input.timeoutMs)
  let requestStarted = false
  try {
    const body = input.body === undefined ? undefined : JSON.stringify(input.body)
    const headers: Record<string, string> = {
      ...(body === undefined ? {} : { "content-type": "application/json" }),
      ...(input.headers ?? {}),
    }
    requestStarted = true
    const response = await window.fetch(input.url, {
      method: input.method,
      credentials: "same-origin",
      mode: "same-origin",
      redirect: "error",
      signal: controller.signal,
      ...(Object.keys(headers).length > 0 ? { headers } : {}),
      ...(body === undefined ? {} : { body }),
    })

    if (!response.ok) {
      await response.body?.cancel().catch(() => undefined)
      return { kind: "HttpError", status: response.status }
    }

    const reader = response.body?.getReader()
    const decoder = new TextDecoder()
    let byteCount = 0
    let text = ""
    if (reader) {
      while (true) {
        const chunk = await reader.read()
        if (chunk.done) break
        byteCount += chunk.value.byteLength
        if (byteCount > input.maxResponseBytes) {
          await reader.cancel().catch(() => undefined)
          return {
            kind: "ResponseTooLarge",
            status: response.status,
            maxResponseBytes: input.maxResponseBytes,
          }
        }
        text += decoder.decode(chunk.value, { stream: true })
      }
      text += decoder.decode()
    }

    try {
      return {
        kind: "Success",
        status: response.status,
        value: text ? JSON.parse(text) : null,
      }
    } catch {
      return { kind: "InvalidJson", status: response.status }
    }
  } catch {
    return {
      kind: "RequestFailed",
      outcome: requestStarted ? "unknown" : "not-sent",
    }
  } finally {
    window.clearTimeout(timeout)
  }
}

/**
 * Relay-level CDP guardrails.
 *
 * The relay refuses a small set of CDP methods that would destroy the user's
 * real browser state (Browser Control drives the user's own browser, with
 * their real logins). Read-only sessions additionally refuse input-dispatching
 * methods so "go look at X" tasks cannot click or type.
 *
 * Pure module: given a method and session context, return a rejection message
 * or null. The relay turns a rejection into a normal CDP error response for
 * that command id, so the calling script fails loudly without breaking the
 * connection.
 */

const alwaysBlocked = new Map<string, string>([
  ["Network.clearBrowserCookies", "it would log the user out of every site in their browser"],
  ["Network.clearBrowserCache", "it would clear the user's entire browser cache"],
  ["Storage.clearCookies", "it would log the user out of every site in their browser"],
  ["Browser.close", "it would close the user's browser"],
])

const readOnlyBlockedPrefixes = ["Input."] as const

export type GuardContext = {
  readonly method: string
  readonly readOnly: boolean
  readonly sessionId?: string | undefined
}

/**
 * Returns a human-readable rejection message when the method must be blocked,
 * or null when the command may be forwarded to the browser.
 */
export function guardCdpMethod(context: GuardContext): string | null {
  const reason = alwaysBlocked.get(context.method)
  if (reason) {
    return `Browser Control blocked ${context.method}: ${reason}. This command is always blocked by the relay.`
  }
  if (context.readOnly && readOnlyBlockedPrefixes.some((prefix) => context.method.startsWith(prefix))) {
    const session = context.sessionId ? `Session ${context.sessionId}` : "This session"
    return `${session} is read-only: ${context.method} is blocked. Use a session created without --read-only to interact with pages.`
  }
  return null
}

import { ClientCdpSessionAlias, type CdpClientPool } from "./cdp-client-pool.ts"
import { canClientSeeTarget } from "./cdp-visibility.ts"
import type { CdpRequest, TargetInfo } from "./protocol.ts"
import { getString, isRestrictedTarget } from "./relay-helpers.ts"
import type { ChildTarget, ConnectedTarget } from "./relay-types.ts"
import { shouldExposeChildTarget, type TargetRegistry } from "./target-registry.ts"

const rootRoutableBrowserContextMethods = new Set([
  "Browser.grantPermissions",
  "Browser.resetPermissions",
  "Storage.getCookies",
  "Storage.setCookies",
  "Storage.clearCookies",
])

export function isRootRoutableBrowserContextMethod(method: string): boolean {
  return rootRoutableBrowserContextMethods.has(method)
}

export type CdpRoutedSession = {
  readonly tabId: number
  readonly rootSessionId: string
  readonly chromeSessionId?: string
}

export class CdpRouter<Client extends object> {
  constructor(
    private readonly clients: CdpClientPool<Client>,
    private readonly registry: TargetRegistry,
  ) {}

  canSeeTarget(client: Client, target: ConnectedTarget): boolean {
    return this.clients.has(client) && this.canSessionSeeTarget(this.clients.sessionId(client), target)
  }

  canSessionSeeTarget(clientSessionId: string | undefined, target: ConnectedTarget): boolean {
    return canClientSeeTarget({
      clientSessionId,
      targetOwnerSessionId: target.browserControlSessionId,
      targetOwner: target.owner,
      clientHasOwnedTarget: clientSessionId !== undefined && this.registry
        .listRootTargets()
        .some((candidate) => candidate.browserControlSessionId === clientSessionId),
    })
  }

  canSeeTab(client: Client, tabId: number): boolean {
    const rootTarget = this.registry.tabTargets.get(tabId)
    return rootTarget ? this.canSeeTarget(client, rootTarget) : false
  }

  preferredRoot(client: Client, browserContextId?: string): ConnectedTarget | undefined {
    const clientSessionId = this.clients.sessionId(client)
    const candidates = this.registry.listRootTargets().filter((target) => {
      if (target.crashed) return false
      if (browserContextId !== undefined && target.targetInfo.browserContextId !== browserContextId) return false
      return clientSessionId !== undefined
        ? target.browserControlSessionId === clientSessionId
        : this.canSeeTarget(client, target)
    })
    if (candidates.length === 0) return undefined
    if (clientSessionId !== undefined || candidates.length === 1) return candidates[0]
    const contexts = new Set(candidates.map((target) => target.targetInfo.browserContextId))
    // CDP omits browserContextId for the singleton default context. Matching
    // absence is therefore a validated default-context identity, not a guess.
    if (contexts.size === 1) {
      return candidates[0]
    }
    return undefined
  }

  isBrowserAlias(client: Client, sessionId: string): boolean {
    return ClientCdpSessionAlias.$is("Browser")(this.clients.alias(client, sessionId))
  }

  visibleRoots(client: Client): ConnectedTarget[] {
    return this.registry.listRootTargets().filter((target) => this.canSeeTarget(client, target))
  }

  rootForSession(client: Client, sessionId: string): ConnectedTarget | undefined {
    const target = this.registry.targets.get(sessionId)
    return target && this.canSeeTarget(client, target) ? target : undefined
  }

  targetForAttach(client: Client, targetId: string): ConnectedTarget | ChildTarget | undefined {
    const root = this.registry.targetsByTargetId.get(targetId)
    if (root) return this.canSeeTarget(client, root) ? root : undefined
    const child = this.registry.childTargetsByTargetId.get(targetId)
    return child && this.canSeeTab(client, child.tabId) ? child : undefined
  }

  targetInfo(client: Client, options: {
    readonly targetId?: string
    readonly sessionId?: string
  }): ConnectedTarget | ChildTarget | undefined {
    const alias = options.sessionId ? this.clients.alias(client, options.sessionId) : undefined
    const aliasedTargetId = ClientCdpSessionAlias.$is("Target")(alias) ? alias.targetId : undefined
    const target = (options.targetId
      ? this.registry.targetsByTargetId.get(options.targetId) ?? this.registry.childTargetsByTargetId.get(options.targetId)
      : undefined) ??
      (aliasedTargetId
        ? this.registry.targetsByTargetId.get(aliasedTargetId) ?? this.registry.childTargetsByTargetId.get(aliasedTargetId)
        : undefined) ??
      (options.sessionId
        ? this.registry.targets.get(options.sessionId) ?? this.registry.childTargets.get(options.sessionId)
        : undefined)
    if (!target) return undefined
    return "owner" in target
      ? this.canSeeTarget(client, target) ? target : undefined
      : this.canSeeTab(client, target.tabId) ? target : undefined
  }

  session(client: Client, requestedSessionId: string): CdpRoutedSession | undefined {
    const sessionAlias = this.clients.alias(client, requestedSessionId)
    if (ClientCdpSessionAlias.$is("Browser")(sessionAlias)) return undefined
    const alias = ClientCdpSessionAlias.$is("Target")(sessionAlias) ? sessionAlias : undefined
    const target = alias
      ? this.registry.targetsByTargetId.get(alias.targetId) ?? this.registry.childTargetsByTargetId.get(alias.targetId)
      : this.registry.targets.get(requestedSessionId) ?? this.registry.childTargets.get(requestedSessionId)
    if (!target || !this.canSeeTab(client, target.tabId)) return undefined
    const rootSessionId = this.registry.tabTargets.get(target.tabId)?.sessionId
    if (!rootSessionId) return undefined
    const expectedChromeSessionId = "owner" in target ? undefined : target.sessionId
    if (alias && (alias.tabId !== target.tabId || alias.chromeSessionId !== expectedChromeSessionId)) return undefined
    return {
      tabId: target.tabId,
      rootSessionId,
      ...(expectedChromeSessionId ? { chromeSessionId: expectedChromeSessionId } : {}),
    }
  }

  resolveCommandRoute(client: Client, message: CdpRequest): CdpRoutedSession {
    const browserAlias = message.sessionId !== undefined && this.isBrowserAlias(client, message.sessionId)
    const rootRoutable = isRootRoutableBrowserContextMethod(message.method) && (!message.sessionId || browserAlias)
    const requestedBrowserContextId = getString(message.params, "browserContextId")
    const preferredRoot = rootRoutable ? this.preferredRoot(client, requestedBrowserContextId) : undefined
    const route = rootRoutable && preferredRoot
      ? { tabId: preferredRoot.tabId, rootSessionId: preferredRoot.sessionId }
      : message.sessionId
      ? this.session(client, message.sessionId)
      : undefined
    if (route) return route
    throw new Error(rootRoutable
      ? requestedBrowserContextId !== undefined
        ? `A healthy visible root target in browser context ${requestedBrowserContextId} is required for ${message.method}`
        : this.clients.sessionId(client) === undefined
        ? `Exactly one visible browser context is required for ${message.method}`
        : `A healthy session-owned root target is required for ${message.method}`
      : message.sessionId
      ? `Unknown CDP session ${message.sessionId} for ${message.method}`
      : `CDP sessionId is required for ${message.method}`)
  }

  reconcileClient(client: Client): void {
    this.clients.pruneInvisible(client, (tabId) => this.canSeeTab(client, tabId))
  }

  visibleTargetInfos(client: Client): TargetInfo[] {
    return this.registry.allTargetInfos({
      isRestrictedTarget,
      isVisibleTarget: (target) => {
        return this.canSeeTab(client, target.tabId) && ("owner" in target || shouldExposeChildTarget(target))
      },
    })
  }
}

import type { WebSocket } from "ws"
import type { CdpRequest, JsonObject, TargetInfo } from "./protocol.ts"
import { getObject, getString, sendCdpEvent } from "./relay-helpers.ts"
import type { ChildTarget } from "./relay-types.ts"
import { shouldExposeChildTarget, type TargetRegistry } from "./target-registry.ts"
import type { CdpClientPool } from "./cdp-client-pool.ts"

export function removeDefaultLightColorSchemeEmulation(message: CdpRequest): CdpRequest {
  if (message.method !== "Emulation.setEmulatedMedia") {
    return message
  }
  const features = Array.isArray(message.params?.features) ? message.params.features : []
  const isExplicit = features.some((feature) => {
    const object = getObject(feature)
    return object?.name === "__bc_explicit__"
  })
  if (isExplicit) {
    return {
      ...message,
      params: {
        ...message.params,
        features: features.filter((feature) => {
          const object = getObject(feature)
          return object?.name !== "__bc_explicit__"
        }),
      },
    }
  }
  const hasDefaultLightColorScheme = features.some((feature) => {
    const object = getObject(feature)
    return object?.name === "prefers-color-scheme" && object.value === "light"
  })
  if (!hasDefaultLightColorScheme) {
    return message
  }
  return {
    ...message,
    params: {
      ...message.params,
      features: features.filter((feature) => {
        const object = getObject(feature)
        return object?.name !== "prefers-color-scheme"
      }),
    },
  }
}

export function replayChildTargetsForParent<Client extends Pick<WebSocket, "send">>(options: {
  readonly socket: Client
  readonly parentSessionId: string
  readonly registry: TargetRegistry
  readonly clients: CdpClientPool<Client>
}): void {
  for (const target of options.registry.childTargets.values()) {
    if (target.parentSessionId === options.parentSessionId && shouldExposeChildTarget(target)) {
      replayFrameEventsForChild({ socket: options.socket, registry: options.registry, target })
      options.clients.announce(options.socket, target)
      replayChildFrameNavigation({ socket: options.socket, registry: options.registry, target })
    }
  }
}

function replayFrameEventsForChild(options: { readonly socket: Pick<WebSocket, "send">; readonly registry: TargetRegistry; readonly target: ChildTarget }): void {
  if (options.target.targetInfo.type !== "iframe") {
    return
  }
  const frameEvents = options.registry.tabFrameEvents.get(options.target.tabId)?.get(options.target.targetInfo.targetId)
  if (!frameEvents) {
    return
  }
  if (frameEvents.attached) {
    sendCdpEvent(options.socket, { sessionId: options.target.parentSessionId, method: "Page.frameAttached", params: frameEvents.attached })
  }
  if (frameEvents.navigated) {
    sendCdpEvent(options.socket, { sessionId: options.target.parentSessionId, method: "Page.frameNavigated", params: frameEvents.navigated })
  }
}

export function replayChildFrameNavigation(options: { readonly socket: Pick<WebSocket, "send">; readonly registry: TargetRegistry; readonly target: ChildTarget }): void {
  const navigationParams = childFrameNavigationParams({ registry: options.registry, target: options.target })
  if (!navigationParams) {
    return
  }
  // Stock Playwright does not apply Page.getFrameTree to child iframe sessions;
  // replay the current navigation on the child session so reconnects do not
  // leave OOPIF frames with an empty URL.
  sendCdpEvent(options.socket, { sessionId: options.target.sessionId, method: "Page.frameNavigated", params: navigationParams })
}

function childFrameNavigationParams(options: { readonly registry: TargetRegistry; readonly target: ChildTarget }): JsonObject | undefined {
  if (options.target.targetInfo.type !== "iframe") {
    return undefined
  }
  const frameEvents = options.registry.findFrameEventsForChild(options.target)
  const navigated = frameEvents?.navigated
  const frame = getObject(navigated?.frame)
  if (navigated && frame) {
    return {
      ...navigated,
      frame: {
        ...frame,
        id: options.target.targetInfo.targetId,
        url: options.target.targetInfo.url || (getString(frame, "url") ?? ""),
        ...(options.target.targetInfo.parentFrameId ? { parentId: options.target.targetInfo.parentFrameId } : {}),
      },
    }
  }
  if (!options.target.targetInfo.url) {
    return undefined
  }
  const gatedAPIFeatures: string[] = []
  return {
    frame: {
      id: options.target.targetInfo.targetId,
      loaderId: options.target.targetInfo.targetId,
      url: options.target.targetInfo.url,
      domainAndRegistry: "",
      securityOrigin: new URL(options.target.targetInfo.url).origin,
      mimeType: "text/html",
      adFrameStatus: { adFrameType: "none" },
      secureContextType: "Secure",
      crossOriginIsolatedContextType: "NotIsolated",
      gatedAPIFeatures,
      ...(options.target.targetInfo.parentFrameId ? { parentId: options.target.targetInfo.parentFrameId } : {}),
    },
  }
}

export function replayTargetCreated(options: { readonly socket: Pick<WebSocket, "send">; readonly targetInfos: readonly TargetInfo[] }): void {
  for (const targetInfo of options.targetInfos) {
    sendCdpEvent(options.socket, { method: "Target.targetCreated", params: { targetInfo } })
  }
}
